# ==== Module: numerical_solvers.LAX_torch (numerical_solvers/LAX_torch.py) ====
import numpy as np
import torch
from config import cs, rho_o, const, G, KX, KY, KZ

# Device setup - check at module import
has_gpu = torch.cuda.is_available()
device = torch.device("cuda:0" if has_gpu else "cpu")
dtype = torch.float64
if has_gpu:
    print(f"LAX_torch: GPU available, using device: {device}")
    print(f"  GPU name: {torch.cuda.get_device_name(0)}")
else:
    print(f"LAX_torch: No GPU available, using device: {device}")

def fft_solver_torch(rho, Lx, nx, Ly, ny):
    """
    PyTorch FFT solver for Poisson equation (gravitational potential).
    """
    dx = Lx / nx
    dy = Ly / ny
    
    # Calculate the Fourier modes of the gas density
    rhohat = torch.fft.fft2(rho)
    
    # Calculate the wave numbers in x and y directions
    kx = 2 * np.pi * torch.fft.fftfreq(nx, d=dx).to(device)
    ky = 2 * np.pi * torch.fft.fftfreq(ny, d=dy).to(device)
    
    # Construct the discrete Laplacian operator in Fourier space
    # This ensures consistency with finite-difference gradients used in LAX scheme
    kx_mesh, ky_mesh = torch.meshgrid(kx, ky, indexing='xy')
    # Transpose to match FFT2 output layout (nx, ny)
    laplace = (2*(torch.cos(kx_mesh.T*dx)-1)/(dx**2) + 
               2*(torch.cos(ky_mesh.T*dy)-1)/(dy**2))
    
    # Handle zero mode (k=0) - set to small value to avoid division by zero
    laplace = torch.where(laplace == 0, torch.tensor(1e-9, device=device, dtype=dtype), laplace)
    
    # Solve for the potential in Fourier space
    phihat = rhohat / laplace
    
    # Transform back to real space
    phi = torch.real(torch.fft.ifft2(phihat))
    
    return phi

def fft_solver_torch_3d(rho, Lx, nx, Ly, ny, Lz, nz):
    dx = Lx / nx
    dy = Ly / ny
    dz = Lz / nz
    rhohat = torch.fft.fftn(rho)
    kx = 2 * np.pi * torch.fft.fftfreq(nx, d=dx).to(device)
    ky = 2 * np.pi * torch.fft.fftfreq(ny, d=dy).to(device)
    kz = 2 * np.pi * torch.fft.fftfreq(nz, d=dz).to(device)
    kx_mesh, ky_mesh, kz_mesh = torch.meshgrid(kx, ky, kz, indexing='ij')
    # Use discrete Laplacian for consistency with finite-difference scheme
    laplace = (2*(torch.cos(kx_mesh*dx)-1)/(dx**2) + 
               2*(torch.cos(ky_mesh*dy)-1)/(dy**2) + 
               2*(torch.cos(kz_mesh*dz)-1)/(dz**2))
    laplace = torch.where(laplace == 0, torch.tensor(1e-9, device=device, dtype=dtype), laplace)
    phihat = rhohat / laplace
    phi = torch.real(torch.fft.ifftn(phihat))
    return phi

def generate_velocity_field_power_spectrum_torch(nx, ny, Lx, Ly, power_index=-3.0, amplitude=0.02, random_seed=None):
    """
    PyTorch implementation for generating a 2D velocity field with a power-law spectrum.
    
    This function generates velocity fields directly at the target resolution (nx, ny)
    without any downsampling or cutoff strategies.
    """
    # Use NumPy's random generator for consistency with CPU solver
    if random_seed is not None:
        rng = np.random.default_rng(random_seed)
    else:
        rng = np.random.default_rng()

    def synthesize_component():
        # 1. Generate random field at target resolution using NumPy (for consistency)
        field_np = rng.standard_normal((nx, ny))
        field = torch.from_numpy(field_np).to(device=device, dtype=dtype)
        F = torch.fft.fft2(field)
        
        # 2. Construct k-space grid at target resolution
        kx = 2 * np.pi * torch.fft.fftfreq(nx, d=Lx / nx).to(device)
        ky = 2 * np.pi * torch.fft.fftfreq(ny, d=Ly / ny).to(device)
        kxg, kyg = torch.meshgrid(kx, ky, indexing='ij')
        
        kk = torch.sqrt(kxg**2 + kyg**2)
        kk[0, 0] = 1.0  # Avoid division by zero
        
        # 3. Apply power-law filter
        filt = kk**(power_index / 2.0)
        filt[kk == 0] = 0.0
        
        F_filtered = F * filt
        
        # 4. Transform back to real space
        comp = torch.real(torch.fft.ifft2(F_filtered))
        
        # 5. Normalize the field
        comp -= torch.mean(comp)
        std = torch.std(comp)
        if std > 0:
            comp = comp * (amplitude / std)
        
        return comp

    vx0 = synthesize_component()
    vy0 = synthesize_component()
    return vx0, vy0

def lax_solution_torch(time_val, N, nu, lam, num_of_waves, rho_1, gravity=False, use_velocity_ps=False, 
                         ps_index=-3.0, vel_rms=0.02, random_seed=None):
    """
    PyTorch implementation of the LAX method for solving hydrodynamic equations.
    This version is designed to run on a GPU for accelerated computation.
    """
    # Verify device is still correct (in case CUDA becomes available after import)
    current_device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
    if current_device != device:
        print(f"Warning: Device changed from {device} to {current_device}")
    
    # Grid and Domain Parameters
    Lx = Ly = lam * num_of_waves
    c_s = cs

    # Grid setup
    Nx = Ny = N
    dx = dy = float(Lx / Nx)

    # Tensors Initialization
    # Use linspace and slice to match NumPy's endpoint=False behavior
    x = torch.linspace(0, Lx, Nx+1, device=device, dtype=dtype)[:-1]
    y = torch.linspace(0, Ly, Ny+1, device=device, dtype=dtype)[:-1]
    xx, yy = torch.meshgrid(x, y, indexing='ij')

    rho0 = torch.zeros((Nx, Ny), device=device, dtype=dtype)
    vx0 = torch.zeros((Nx, Ny), device=device, dtype=dtype)
    vy0 = torch.zeros((Nx, Ny), device=device, dtype=dtype)
    
    # Initial Conditions
    if use_velocity_ps:
        rho0 = rho_o * torch.ones((Nx, Ny), device=device, dtype=dtype)
        vx0, vy0 = generate_velocity_field_power_spectrum_torch(Nx, Ny, Lx, Ly, 
                                                              power_index=ps_index, 
                                                              amplitude=vel_rms, 
                                                              random_seed=random_seed)
    else:
        # Sinusoidal perturbations: Use 2D wave pattern: cos(KX*x + KY*y)
        KX_tensor = torch.tensor(KX, device=device, dtype=dtype)
        KY_tensor = torch.tensor(KY, device=device, dtype=dtype)
        rho0 = rho_o + rho_1 * torch.cos(KX_tensor * xx + KY_tensor * yy)
    
    # Copy initial conditions to rho1, vx1, vy1 for t=0 case
    rho1 = rho0.clone()
    vx1 = vx0.clone()
    vy1 = vy0.clone()

    # Set velocity initial conditions for sinusoidal perturbations
    if not use_velocity_ps:
        if not gravity:
            # No gravity case
            v_1 = (c_s * rho_1) / rho_o  # velocity perturbation
            k_magnitude = torch.sqrt(KX_tensor**2 + KY_tensor**2)
            if k_magnitude > 0:
                vx0 = v_1 * torch.cos(KX_tensor * xx + KY_tensor * yy) * (KX_tensor / k_magnitude)
                vy0 = v_1 * torch.cos(KX_tensor * xx + KY_tensor * yy) * (KY_tensor / k_magnitude)
            else:
                vx0 = v_1 * torch.cos(KX_tensor * xx + KY_tensor * yy)
                vy0 = torch.zeros_like(xx)
        else:
            # Gravity case: need to check Jeans length
            jeans = torch.sqrt(torch.tensor(4 * np.pi**2 * c_s**2 / (const * G * rho_o), device=device, dtype=dtype))
            
            if lam >= jeans.item():
                # Gravitational instability case
                alpha = torch.sqrt(torch.tensor(const * G * rho_o - c_s**2 * (2 * np.pi / lam)**2, device=device, dtype=dtype))
                v_1 = (rho_1 / rho_o) * (alpha / (2 * np.pi / lam))
                k_magnitude = torch.sqrt(KX_tensor**2 + KY_tensor**2)
                if k_magnitude > 0:
                    vx0 = -v_1 * torch.sin(KX_tensor * xx + KY_tensor * yy) * (KX_tensor / k_magnitude)
                    vy0 = -v_1 * torch.sin(KX_tensor * xx + KY_tensor * yy) * (KY_tensor / k_magnitude)
                else:
                    vx0 = -v_1 * torch.sin(KX_tensor * xx + KY_tensor * yy)
                    vy0 = torch.zeros_like(xx)
            else:
                # Oscillatory regime
                alpha = torch.sqrt(torch.tensor(c_s**2 * (2 * np.pi / lam)**2 - const * G * rho_o, device=device, dtype=dtype))
                v_1 = (rho_1 / rho_o) * (alpha / (2 * np.pi / lam))
                k_magnitude = torch.sqrt(KX_tensor**2 + KY_tensor**2)
                if k_magnitude > 0:
                    vx0 = v_1 * torch.cos(KX_tensor * xx + KY_tensor * yy) * (KX_tensor / k_magnitude)
                    vy0 = v_1 * torch.cos(KX_tensor * xx + KY_tensor * yy) * (KY_tensor / k_magnitude)
                else:
                    vx0 = v_1 * torch.cos(KX_tensor * xx + KY_tensor * yy)
                    vy0 = torch.zeros_like(xx)
        
        # Update vx1 and vy1 after setting initial velocities
        vx1 = vx0.clone()
        vy1 = vy0.clone()

    Px0 = rho0 * vx0
    Py0 = rho0 * vy0
    
    # Initialize gravitational potential if needed
    phi0 = torch.zeros((Nx, Ny), device=device, dtype=dtype)
    phi1 = torch.zeros((Nx, Ny), device=device, dtype=dtype)
    
    if gravity:
        # Calculate initial potential using FFT solver
        phi0 = fft_solver_torch(const * (rho0 - rho_o), Lx, Nx, Ly, Ny)

    # --- CORRECTED TIME-STEPPING LOOP ---
    t = 0.0
    k = 0
    # Initial dt for the first step
    vmax_initial = max(torch.max(torch.abs(vx0)).item(), torch.max(torch.abs(vy0)).item(), c_s)
    dt = nu * dx / vmax_initial

    while t < time_val:
        # Ensure the last step doesn't overshoot the final time
        if t + dt > time_val:
            dt = time_val - t

        mux = dt / (2 * dx)
        muy = dt / (2 * dy)

        # Evolve one step
        rho1 = (0.25) * (torch.roll(rho0, -1, dims=0) + torch.roll(rho0, 1, dims=0) +
                         torch.roll(rho0, -1, dims=1) + torch.roll(rho0, 1, dims=1)) \
            - (mux * (torch.roll(rho0, -1, dims=0) * torch.roll(vx0, -1, dims=0) - torch.roll(rho0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) \
            - (muy * (torch.roll(rho0, -1, dims=1) * torch.roll(vy0, -1, dims=1) - torch.roll(rho0, 1, dims=1) * torch.roll(vy0, 1, dims=1)))

        if not gravity:
            Px1 = (0.25) * (torch.roll(Px0, -1, dims=0) + torch.roll(Px0, 1, dims=0) +
                            torch.roll(Px0, -1, dims=1) + torch.roll(Px0, 1, dims=1)) \
                - (mux * (torch.roll(Px0, -1, dims=0) * torch.roll(vx0, -1, dims=0) - torch.roll(Px0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) \
                - (muy * (torch.roll(Px0, -1, dims=1) * torch.roll(vy0, -1, dims=1) - torch.roll(Px0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) \
                - ((c_s**2) * mux * (torch.roll(rho0, -1, dims=0) - torch.roll(rho0, 1, dims=0)))

            Py1 = (0.25) * (torch.roll(Py0, -1, dims=0) + torch.roll(Py0, 1, dims=0) +
                            torch.roll(Py0, -1, dims=1) + torch.roll(Py0, 1, dims=1)) \
                - (muy * (torch.roll(Py0, -1, dims=1) * torch.roll(vy0, -1, dims=1) - torch.roll(Py0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) \
                - (mux * (torch.roll(Py0, -1, dims=0) * torch.roll(vx0, -1, dims=0) - torch.roll(Py0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) \
                - ((c_s**2) * muy * (torch.roll(rho0, -1, dims=1) - torch.roll(rho0, 1, dims=1)))
        else:
            # With self-gravity
            Px1 = (0.25) * (torch.roll(Px0, -1, dims=0) + torch.roll(Px0, 1, dims=0) +
                            torch.roll(Px0, -1, dims=1) + torch.roll(Px0, 1, dims=1)) \
                - (mux * (torch.roll(Px0, -1, dims=0) * torch.roll(vx0, -1, dims=0) - torch.roll(Px0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) \
                - (muy * (torch.roll(Px0, -1, dims=1) * torch.roll(vy0, -1, dims=1) - torch.roll(Px0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) \
                - ((c_s**2) * mux * (torch.roll(rho0, -1, dims=0) - torch.roll(rho0, 1, dims=0))) \
                - (mux * rho0 * (torch.roll(phi0, -1, dims=0) - torch.roll(phi0, 1, dims=0)))

            Py1 = (0.25) * (torch.roll(Py0, -1, dims=0) + torch.roll(Py0, 1, dims=0) +
                            torch.roll(Py0, -1, dims=1) + torch.roll(Py0, 1, dims=1)) \
                - (muy * (torch.roll(Py0, -1, dims=1) * torch.roll(vy0, -1, dims=1) - torch.roll(Py0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) \
                - (mux * (torch.roll(Py0, -1, dims=0) * torch.roll(vx0, -1, dims=0) - torch.roll(Py0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) \
                - ((c_s**2) * muy * (torch.roll(rho0, -1, dims=1) - torch.roll(rho0, 1, dims=1))) \
                - (muy * rho0 * (torch.roll(phi0, -1, dims=1) - torch.roll(phi0, 1, dims=1)))
            
            # Update gravitational potential
            phi1 = fft_solver_torch(const * (rho1 - rho_o), Lx, Nx, Ly, Ny)

        vx1 = Px1 / rho1
        vy1 = Py1 / rho1
        
        # Update state for next iteration
        rho0, vx0, vy0 = rho1, vx1, vy1
        Px0, Py0 = Px1, Py1
        if gravity:
            phi0 = phi1
        
        # Increment time and step counter
        t += dt
        k += 1

        # Calculate dt for the *next* step
        vmax = max(torch.max(torch.abs(vx0)).item(), torch.max(torch.abs(vy0)).item())
        dt1 = nu * dx / vmax if vmax > 1e-9 else float('inf')
        dt2 = nu * dx / c_s
        dt = min(dt1, dt2)

    n = k
    rho_max = torch.max(rho0).item()
    
    return x.cpu().numpy(), rho0.cpu().numpy(), vx0.cpu().numpy(), vy0.cpu().numpy(), None, n, rho_max


def lax_solution_3d_sinusoidal_torch(time_val, N, nu, lam, num_of_waves, rho_1, gravity=True):
    current_device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
    Nx = Ny = Nz = int(N)
    Lx = Ly = Lz = lam * num_of_waves
    dx = float(Lx / Nx)
    dy = float(Ly / Ny)
    dz = float(Lz / Nz)
    c_s = cs

    x = torch.linspace(0, Lx, Nx+1, device=device, dtype=dtype)[:-1]
    y = torch.linspace(0, Ly, Ny+1, device=device, dtype=dtype)[:-1]
    z = torch.linspace(0, Lz, Nz+1, device=device, dtype=dtype)[:-1]
    xx, yy, zz = torch.meshgrid(x, y, z, indexing='ij')

    rho0 = rho_o + rho_1 * torch.cos(torch.tensor(KX, device=device, dtype=dtype) * xx +
                                     torch.tensor(KY, device=device, dtype=dtype) * yy +
                                     torch.tensor(KZ, device=device, dtype=dtype) * zz)

    Px0 = rho0 * 0
    Py0 = rho0 * 0
    Pz0 = rho0 * 0

    if gravity:
        jeans = torch.sqrt(torch.tensor(4*np.pi**2*cs**2/(const*G*rho_o), device=device, dtype=dtype))
        if lam >= jeans.item():
            alpha = torch.sqrt(torch.tensor(const*G*rho_o-cs**2*(2*np.pi/lam)**2, device=device, dtype=dtype))
            v_1  = (rho_1/rho_o) * (alpha/(2*np.pi/lam))
            wave_field = -v_1 * torch.sin(torch.tensor(KX, device=device, dtype=dtype) * xx +
                                          torch.tensor(KY, device=device, dtype=dtype) * yy +
                                          torch.tensor(KZ, device=device, dtype=dtype) * zz)
        else:
            alpha = torch.sqrt(torch.tensor(cs**2*(2*np.pi/lam)**2 - const*G*rho_o, device=device, dtype=dtype))
            v_1 = (rho_1/rho_o) * (alpha/(2*np.pi/lam))
            wave_field = v_1 * torch.cos(torch.tensor(KX, device=device, dtype=dtype) * xx +
                                         torch.tensor(KY, device=device, dtype=dtype) * yy +
                                         torch.tensor(KZ, device=device, dtype=dtype) * zz)
    else:
        v_1 = (cs * rho_1) / rho_o
        wave_field = v_1 * torch.cos(torch.tensor(KX, device=device, dtype=dtype) * xx +
                                     torch.tensor(KY, device=device, dtype=dtype) * yy +
                                     torch.tensor(KZ, device=device, dtype=dtype) * zz)

    k_mag = np.sqrt(KX**2 + KY**2 + KZ**2)
    if k_mag > 0:
        vx0 = wave_field * (KX / k_mag)
        vy0 = wave_field * (KY / k_mag)
        vz0 = wave_field * (KZ / k_mag)
    else:
        vx0 = wave_field
        vy0 = torch.zeros_like(vx0)
        vz0 = torch.zeros_like(vx0)

    Px0 = rho0 * vx0
    Py0 = rho0 * vy0
    Pz0 = rho0 * vz0

    phi0 = torch.zeros_like(rho0)
    phi1 = torch.zeros_like(rho0)
    if gravity:
        phi0 = fft_solver_torch_3d(const*(rho0-rho_o), Lx, Nx, Ly, Ny, Lz, Nz)

    t_val = 0.0
    k_iter = 0
    vmax_initial = max(torch.max(torch.abs(vx0)).item(), torch.max(torch.abs(vy0)).item(), torch.max(torch.abs(vz0)).item(), cs)
    dt = nu * dx / vmax_initial

    while t_val < time_val:
        if t_val + dt > time_val:
            dt = time_val - t_val

        mux = dt / (2 * dx)
        muy = dt / (2 * dy)
        muz = dt / (2 * dz)

        rho1 = (1/6)*(torch.roll(rho0,-1,0) + torch.roll(rho0,1,0) +
                      torch.roll(rho0,-1,1) + torch.roll(rho0,1,1) +
                      torch.roll(rho0,-1,2) + torch.roll(rho0,1,2)) \
               - mux*(torch.roll(rho0,-1,0)*torch.roll(vx0,-1,0) - torch.roll(rho0,1,0)*torch.roll(vx0,1,0)) \
               - muy*(torch.roll(rho0,-1,1)*torch.roll(vy0,-1,1) - torch.roll(rho0,1,1)*torch.roll(vy0,1,1)) \
               - muz*(torch.roll(rho0,-1,2)*torch.roll(vz0,-1,2) - torch.roll(rho0,1,2)*torch.roll(vz0,1,2))

        Px1 = (1/6)*(torch.roll(Px0,-1,0) + torch.roll(Px0,1,0) +
                      torch.roll(Px0,-1,1) + torch.roll(Px0,1,1) +
                      torch.roll(Px0,-1,2) + torch.roll(Px0,1,2)) \
              - mux*(torch.roll(Px0,-1,0)*torch.roll(vx0,-1,0) - torch.roll(Px0,1,0)*torch.roll(vx0,1,0)) \
              - muy*(torch.roll(Px0,-1,1)*torch.roll(vy0,-1,1) - torch.roll(Px0,1,1)*torch.roll(vy0,1,1)) \
              - muz*(torch.roll(Px0,-1,2)*torch.roll(vz0,-1,2) - torch.roll(Px0,1,2)*torch.roll(vz0,1,2)) \
              - ((c_s**2)*mux*(torch.roll(rho0,-1,0) - torch.roll(rho0,1,0)))

        Py1 = (1/6)*(torch.roll(Py0,-1,0) + torch.roll(Py0,1,0) +
                      torch.roll(Py0,-1,1) + torch.roll(Py0,1,1) +
                      torch.roll(Py0,-1,2) + torch.roll(Py0,1,2)) \
              - muy*(torch.roll(Py0,-1,1)*torch.roll(vy0,-1,1) - torch.roll(Py0,1,1)*torch.roll(vy0,1,1)) \
              - mux*(torch.roll(Py0,-1,0)*torch.roll(vx0,-1,0) - torch.roll(Py0,1,0)*torch.roll(vx0,1,0)) \
              - muz*(torch.roll(Py0,-1,2)*torch.roll(vz0,-1,2) - torch.roll(Py0,1,2)*torch.roll(vz0,1,2)) \
              - ((c_s**2)*muy*(torch.roll(rho0,-1,1) - torch.roll(rho0,1,1)))

        Pz1 = (1/6)*(torch.roll(Pz0,-1,0) + torch.roll(Pz0,1,0) +
                      torch.roll(Pz0,-1,1) + torch.roll(Pz0,1,1) +
                      torch.roll(Pz0,-1,2) + torch.roll(Pz0,1,2)) \
              - muz*(torch.roll(Pz0,-1,2)*torch.roll(vz0,-1,2) - torch.roll(Pz0,1,2)*torch.roll(vz0,1,2)) \
              - mux*(torch.roll(Pz0,-1,0)*torch.roll(vx0,-1,0) - torch.roll(Pz0,1,0)*torch.roll(vx0,1,0)) \
              - muy*(torch.roll(Pz0,-1,1)*torch.roll(vy0,-1,1) - torch.roll(Pz0,1,1)*torch.roll(vy0,1,1)) \
              - ((c_s**2)*muz*(torch.roll(rho0,-1,2) - torch.roll(rho0,1,2)))

        if gravity:
            Px1 -= mux * rho0 * (torch.roll(phi0,-1,0) - torch.roll(phi0,1,0))
            Py1 -= muy * rho0 * (torch.roll(phi0,-1,1) - torch.roll(phi0,1,1))
            Pz1 -= muz * rho0 * (torch.roll(phi0,-1,2) - torch.roll(phi0,1,2))
            phi1 = fft_solver_torch_3d(const*(rho1 - rho_o), Lx, Nx, Ly, Ny, Lz, Nz)

        vx1 = Px1 / rho1
        vy1 = Py1 / rho1
        vz1 = Pz1 / rho1

        rho0, vx0, vy0, vz0 = rho1, vx1, vy1, vz1
        Px0, Py0, Pz0 = Px1, Py1, Pz1
        if gravity:
            phi0 = phi1

        t_val += dt
        k_iter += 1
        vmax = max(torch.max(torch.abs(vx0)).item(), torch.max(torch.abs(vy0)).item(), torch.max(torch.abs(vz0)).item())
        dt1 = nu * dx / vmax if vmax > 1e-9 else float('inf')
        dt2 = nu * dx / c_s
        dt = min(dt1, dt2)

    rho_max = torch.max(rho0).item()
    return (x.cpu().numpy(), y.cpu().numpy(), z.cpu().numpy(),
            rho0.detach().cpu().numpy(), vx0.detach().cpu().numpy(),
            vy0.detach().cpu().numpy(), vz0.detach().cpu().numpy(),
            phi0.detach().cpu().numpy() if gravity else None, k_iter, rho_max)

def lax_solution_warm_start_torch(rho_ic, vx_ic, vy_ic, x_grid, y_grid, 
                                   t_start, t_end, nu=0.5, save_times=None, gravity=True):
    """
    PyTorch implementation: Run FD solver from custom initial conditions (warm-start).
    
    This function allows restarting the FD solver from a PINN state or any custom state,
    enabling efficient generation of FD data for hybrid PINN-FD training.
    
    Args:
        rho_ic: Initial density field (Nx, Ny) - can be numpy array or torch tensor
        vx_ic: Initial x-velocity field (Nx, Ny) - can be numpy array or torch tensor
        vy_ic: Initial y-velocity field (Nx, Ny) - can be numpy array or torch tensor
        x_grid: x coordinates (Nx,) - can be numpy array or torch tensor
        y_grid: y coordinates (Ny,) - can be numpy array or torch tensor
        t_start: Starting time
        t_end: Ending time
        nu: Courant number
        save_times: List of times to save snapshots [default: [t_end]]
        gravity: Whether to include self-gravity (default: True)
    
    Returns:
        Dictionary: {time: (rho, vx, vy, phi, x, y)} for each saved time (all as numpy arrays)
    """
    if save_times is None:
        save_times = [t_end]
    
    # Convert inputs to torch tensors if needed
    if isinstance(rho_ic, np.ndarray):
        rho_ic = torch.from_numpy(rho_ic).to(device=device, dtype=dtype)
    if isinstance(vx_ic, np.ndarray):
        vx_ic = torch.from_numpy(vx_ic).to(device=device, dtype=dtype)
    if isinstance(vy_ic, np.ndarray):
        vy_ic = torch.from_numpy(vy_ic).to(device=device, dtype=dtype)
    if isinstance(x_grid, np.ndarray):
        x_grid = torch.from_numpy(x_grid).to(device=device, dtype=dtype)
    if isinstance(y_grid, np.ndarray):
        y_grid = torch.from_numpy(y_grid).to(device=device, dtype=dtype)
    
    # Domain setup
    Nx, Ny = rho_ic.shape
    Lx = (x_grid[-1] - x_grid[0] + (x_grid[1] - x_grid[0])).item()  # Approximate domain size
    Ly = (y_grid[-1] - y_grid[0] + (y_grid[1] - y_grid[0])).item()
    dx = Lx / Nx
    dy = Ly / Ny
    
    # Physical constants
    c_s = cs
    
    # Initialize from provided ICs
    rho0 = rho_ic.clone()
    vx0 = vx_ic.clone()
    vy0 = vy_ic.clone()
    
    # Calculate initial potential (gravity is always True for collapse problems)
    phi0 = fft_solver_torch(const * (rho0 - rho_o), Lx, Nx, Ly, Ny)
    
    # Initialize flux terms
    Px0 = rho0 * vx0
    Py0 = rho0 * vy0
    
    # Storage for snapshots
    snapshots = {}
    
    # Time-stepping loop
    t = t_start
    k = 0
    
    # Initial dt
    vmax_initial = max(torch.max(torch.abs(vx0)).item(), torch.max(torch.abs(vy0)).item(), c_s)
    dt = nu * dx / vmax_initial
    
    while t < t_end:
        # Check if we should save a snapshot before this step
        for save_t in save_times:
            if t <= save_t < t + dt and save_t not in snapshots:
                # Save current state (convert to numpy for consistency)
                snapshots[save_t] = (
                    rho0.cpu().numpy().copy(),
                    vx0.cpu().numpy().copy(),
                    vy0.cpu().numpy().copy(),
                    phi0.cpu().numpy().copy(),
                    x_grid.cpu().numpy().copy(),
                    y_grid.cpu().numpy().copy()
                )
        
        # Ensure last step doesn't overshoot
        if t + dt > t_end:
            dt = t_end - t
        
        # LAX time-stepping
        mux = dt / (2 * dx)
        muy = dt / (2 * dy)
        
        # Update density
        rho1 = (0.25) * (torch.roll(rho0, -1, dims=0) + torch.roll(rho0, 1, dims=0) +
                        torch.roll(rho0, -1, dims=1) + torch.roll(rho0, 1, dims=1)) - \
               (mux * (torch.roll(rho0, -1, dims=0) * torch.roll(vx0, -1, dims=0) -
                       torch.roll(rho0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) - \
               (muy * (torch.roll(rho0, -1, dims=1) * torch.roll(vy0, -1, dims=1) -
                       torch.roll(rho0, 1, dims=1) * torch.roll(vy0, 1, dims=1)))
        
        # Update momentum (with gravity)
        if gravity:
            Px1 = (0.25) * (torch.roll(Px0, -1, dims=0) + torch.roll(Px0, 1, dims=0) +
                            torch.roll(Px0, -1, dims=1) + torch.roll(Px0, 1, dims=1)) - \
                  (mux * (torch.roll(Px0, -1, dims=0) * torch.roll(vx0, -1, dims=0) -
                          torch.roll(Px0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) - \
                  (muy * (torch.roll(Px0, -1, dims=1) * torch.roll(vy0, -1, dims=1) -
                          torch.roll(Px0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) - \
                  ((c_s**2) * mux * (torch.roll(rho0, -1, dims=0) - torch.roll(rho0, 1, dims=0))) - \
                  (mux * rho0 * (torch.roll(phi0, -1, dims=0) - torch.roll(phi0, 1, dims=0)))
            
            Py1 = (0.25) * (torch.roll(Py0, -1, dims=0) + torch.roll(Py0, 1, dims=0) +
                            torch.roll(Py0, -1, dims=1) + torch.roll(Py0, 1, dims=1)) - \
                  (muy * (torch.roll(Py0, -1, dims=1) * torch.roll(vy0, -1, dims=1) -
                          torch.roll(Py0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) - \
                  (mux * (torch.roll(Py0, -1, dims=0) * torch.roll(vx0, -1, dims=0) -
                          torch.roll(Py0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) - \
                  ((c_s**2) * muy * (torch.roll(rho0, -1, dims=1) - torch.roll(rho0, 1, dims=1))) - \
                  (muy * rho0 * (torch.roll(phi0, -1, dims=1) - torch.roll(phi0, 1, dims=1)))
            
            # Update potential
            phi1 = fft_solver_torch(const * (rho1 - rho_o), Lx, Nx, Ly, Ny)
        else:
            # Without gravity (shouldn't happen for collapse problems, but included for completeness)
            Px1 = (0.25) * (torch.roll(Px0, -1, dims=0) + torch.roll(Px0, 1, dims=0) +
                            torch.roll(Px0, -1, dims=1) + torch.roll(Px0, 1, dims=1)) - \
                  (mux * (torch.roll(Px0, -1, dims=0) * torch.roll(vx0, -1, dims=0) -
                          torch.roll(Px0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) - \
                  (muy * (torch.roll(Px0, -1, dims=1) * torch.roll(vy0, -1, dims=1) -
                          torch.roll(Px0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) - \
                  ((c_s**2) * mux * (torch.roll(rho0, -1, dims=0) - torch.roll(rho0, 1, dims=0)))
            
            Py1 = (0.25) * (torch.roll(Py0, -1, dims=0) + torch.roll(Py0, 1, dims=0) +
                            torch.roll(Py0, -1, dims=1) + torch.roll(Py0, 1, dims=1)) - \
                  (muy * (torch.roll(Py0, -1, dims=1) * torch.roll(vy0, -1, dims=1) -
                          torch.roll(Py0, 1, dims=1) * torch.roll(vy0, 1, dims=1))) - \
                  (mux * (torch.roll(Py0, -1, dims=0) * torch.roll(vx0, -1, dims=0) -
                          torch.roll(Py0, 1, dims=0) * torch.roll(vx0, 1, dims=0))) - \
                  ((c_s**2) * muy * (torch.roll(rho0, -1, dims=1) - torch.roll(rho0, 1, dims=1)))
            
            phi1 = torch.zeros_like(rho1)
        
        # Update velocities
        vx1 = Px1 / rho1
        vy1 = Py1 / rho1
        
        # Update state
        rho0 = rho1
        vx0 = vx1
        vy0 = vy1
        Px0 = Px1
        Py0 = Py1
        if gravity:
            phi0 = phi1
        
        t += dt
        k += 1
        
        # Calculate dt for next step
        vmax = max(torch.max(torch.abs(vx0)).item(), torch.max(torch.abs(vy0)).item())
        dt1 = nu * dx / vmax if vmax > 1e-9 else float('inf')
        dt2 = nu * dx / c_s
        dt = min(dt1, dt2)
    
    # Save final snapshot if not already saved
    if t_end not in snapshots:
        snapshots[t_end] = (
            rho0.cpu().numpy().copy(),
            vx0.cpu().numpy().copy(),
            vy0.cpu().numpy().copy(),
            phi0.cpu().numpy().copy(),
            x_grid.cpu().numpy().copy(),
            y_grid.cpu().numpy().copy()
        )
    
    return snapshots
_register_module('numerical_solvers.LAX_torch', ['device', 'dtype', 'fft_solver_torch', 'fft_solver_torch_3d', 'generate_velocity_field_power_spectrum_torch', 'has_gpu', 'lax_solution_3d_sinusoidal_torch', 'lax_solution_torch', 'lax_solution_warm_start_torch'])

# ==== Module: core.initial_conditions (core/initial_conditions.py) ====
"""
Initial Conditions Module

This module contains all initial condition functions and power spectrum generation
for PINNs training. Extracted from solver.py for better code organization.

Functions:
- initialize_shared_velocity_fields: Setup shared velocity fields for PINN/FD consistency
- generate_power_spectrum_field: Generate vx component using power spectrum
- generate_power_spectrum_field_vy: Generate vy component using power spectrum
- fun_rho_0: Initial density condition
- fun_vx_0: Initial x-velocity condition
- fun_vy_0: Initial y-velocity condition
- func: Placeholder function for phi initial condition
"""

import numpy as np
import torch
from config import (cs, rho_o, N_GRID, POWER_EXPONENT, 
                    PERTURBATION_TYPE, KX, KY, KZ, RANDOM_SEED)
from numerical_solvers.LAX import generate_shared_velocity_field

# Global shared velocity fields for consistent initial conditions
_shared_vx_interp = None
_shared_vy_interp = None

def _ensure_column_tensor(tensor):
    return tensor if tensor.dim() > 1 else tensor.unsqueeze(-1)

def _extract_spatial_coords(coords):
    return coords[:-1] if len(coords) > 1 else coords


def initialize_shared_velocity_fields(lam, num_of_waves, v_1, seed=None):
    """
    Initialize shared velocity fields for consistent PINN/FD initial conditions.
    This should be called once at the beginning of training.
    
    IMPORTANT: The parameters used here (POWER_EXPONENT, v_1=a*cs, seed) MUST match
    the parameters used in FD plotting functions to ensure identical initial conditions.
    All FD visualization functions should use the same defaults.
    
    Args:
        lam: Wavelength
        num_of_waves: Number of waves in domain
        v_1: Velocity amplitude
        seed: Random seed for reproducibility
    
    Returns:
        Tuple (vx_np, vy_np): Velocity field arrays
    """
    global _shared_vx_interp, _shared_vy_interp
    
    if seed is None:
        seed = RANDOM_SEED
    
    # Calculate domain size to match FD solver
    Lx = lam * num_of_waves
    Ly = lam * num_of_waves
    
    # Generate shared velocity fields
    vx_np, vy_np, vx_interp, vy_interp = generate_shared_velocity_field(
        N_GRID, N_GRID, Lx, Ly, 
        power_index=POWER_EXPONENT, 
        amplitude=v_1, 
        random_seed=seed
    )
    
    # Store interpolation functions globally
    _shared_vx_interp = vx_interp
    _shared_vy_interp = vy_interp
    
    return vx_np, vy_np


def _interpolate_shared_field(x, field_interp):
    """
    Helper function to interpolate shared velocity field to collocation points.
    
    Args:
        x: Collocation coordinates [x, y, ...]
        field_interp: Interpolation function from shared fields
    
    Returns:
        Interpolated field values as torch tensor
    """
    # Convert tensor coordinates to numpy for interpolation
    x_np = x[0].detach().cpu().numpy()
    y_np = x[1].detach().cpu().numpy()
    
    # Create coordinate pairs for interpolation
    coords = np.stack([x_np.flatten(), y_np.flatten()], axis=1)
    
    # Interpolate shared velocity field
    field_interp_values = field_interp(coords)
    
    # Convert back to tensor and reshape
    field_tensor = torch.from_numpy(field_interp_values).float().to(x[0].device)
    
    # Ensure correct shape [N, 1]
    if field_tensor.dim() == 1:
        return field_tensor.unsqueeze(-1)
    else:
        return field_tensor


def _generate_power_spectrum_fallback(lam, v_1, x, seed=None):
    """
    Fallback power spectrum generation when shared fields are not available.
    
    Args:
        lam: Wavelength (unused for domain sizing in fallback)
        v_1: Velocity amplitude
        x: Collocation coordinates
        seed: Random seed
    
    Returns:
        Generated power spectrum field
    """
    if seed is None:
        seed = RANDOM_SEED
    
    # Infer domain extents directly from the collocation coordinates to support arbitrary num_of_waves
    # Use conservative defaults if tensors are degenerate (e.g., single point during a unit test)
    x_coords = x[0].detach()
    y_coords = x[1].detach() if len(x) > 1 else x[0].detach()

    xmin_val = torch.min(x_coords).item() if x_coords.numel() > 0 else 0.0
    xmax_val = torch.max(x_coords).item() if x_coords.numel() > 0 else float(lam * 2.0)
    ymin_val = torch.min(y_coords).item() if y_coords.numel() > 0 else 0.0
    ymax_val = torch.max(y_coords).item() if y_coords.numel() > 0 else float(lam * 2.0)

    # Ensure positive lengths; fall back to 2*lam if bounds collapse
    Lx = float(max(xmax_val - xmin_val, 1e-6))
    Ly = float(max(ymax_val - ymin_val, 1e-6))
    if not torch.isfinite(torch.tensor(Lx)) or Lx < 1e-6:
        Lx = float(lam * 2.0)
    if not torch.isfinite(torch.tensor(Ly)) or Ly < 1e-6:
        Ly = float(lam * 2.0)

    dx = Lx / N_GRID
    dy = Ly / N_GRID
    
    # Calculate wave numbers
    kx = 2 * np.pi * torch.fft.fftfreq(N_GRID, dx, device=x[0].device)
    ky = 2 * np.pi * torch.fft.fftfreq(N_GRID, dy, device=x[0].device)
    KX_grid, KY_grid = torch.meshgrid(kx, ky, indexing='ij')
    
    # Calculate magnitude of wave number
    K = torch.sqrt(KX_grid**2 + KY_grid**2)
    
    # Power spectrum: P(k) ~ k^expon
    K_safe = torch.where(K == 0, torch.tensor(1e-10, device=x[0].device), K)
    power_spectrum = K_safe**POWER_EXPONENT
    
    # Remove DC (uniform) mode to avoid bulk drift
    power_spectrum[K == 0] = 0.0
    
    # Safety check: limit extreme values
    power_spectrum = torch.clamp(power_spectrum, 0, 1e6)
    
    # Generate random phases
    torch.manual_seed(seed)
    random_phases = torch.randn(N_GRID, N_GRID, device=x[0].device) + 1j * torch.randn(N_GRID, N_GRID, device=x[0].device)
    
    # Create complex field in Fourier space and transform to real space
    field_fourier = torch.sqrt(power_spectrum) * random_phases
    field_real = torch.real(torch.fft.ifft2(field_fourier))
    
    # Remove any residual mean (bulk flow) and normalize rms to v_1
    field_real = field_real - torch.mean(field_real)
    field_real = field_real / torch.std(field_real) * v_1
    
    # Interpolate to the actual collocation points
    x_norm = torch.clamp(((x[0] - xmin_val) / Lx) * (N_GRID - 1), 0, N_GRID - 1)
    if len(x) > 1:
        y_norm = torch.clamp(((x[1] - ymin_val) / Ly) * (N_GRID - 1), 0, N_GRID - 1)
    else:
        # 1D fallback: mirror x for y to preserve shape
        y_norm = x_norm.clone()
    
    x_idx = torch.round(x_norm).long()
    y_idx = torch.round(y_norm).long()
    
    # Ensure correct tensor shape [N, 1]
    result = field_real[x_idx, y_idx]
    if result.dim() == 1:
        return result.unsqueeze(-1)
    else:
        return result


def generate_power_spectrum_field(lam, v_1, x, seed=None):
    """
    Generate 2D Gaussian random field with power spectrum using shared fields if available.
    
    Args:
        lam: Wavelength
        v_1: Velocity amplitude
        x: Collocation coordinates [x, y, ...]
        seed: Random seed for reproducibility
    
    Returns:
        vx component of velocity field
    """
    if seed is None:
        seed = RANDOM_SEED
    
    # Use shared velocity fields if available
    if _shared_vx_interp is not None:
        return _interpolate_shared_field(x, _shared_vx_interp)
    
    # Fallback to original method if shared fields not available
    return _generate_power_spectrum_fallback(lam, v_1, x, seed)


def generate_power_spectrum_field_vy(lam, v_1, x, seed=None):
    """
    Generate vy component using shared fields if available.
    
    Args:
        lam: Wavelength
        v_1: Velocity amplitude
        x: Collocation coordinates [x, y, ...]
        seed: Random seed for reproducibility
    
    Returns:
        vy component of velocity field
    """
    if seed is None:
        seed = RANDOM_SEED
    
    # Use shared velocity fields if available
    if _shared_vy_interp is not None:
        return _interpolate_shared_field(x, _shared_vy_interp)
    
    # Fallback to original method if shared fields not available
    return _generate_power_spectrum_fallback(lam, v_1, x, seed)


def _compute_wave_phase(spatial_coords, lam):
    """
    Compute wave phase and wave-vector components for sinusoidal perturbations.
    """
    if not spatial_coords:
        raise ValueError("Spatial coordinates are required to compute wave phase.")
    
    x_coord = _ensure_column_tensor(spatial_coords[0])
    zeros = torch.zeros_like(x_coord)
    y_coord = _ensure_column_tensor(spatial_coords[1]) if len(spatial_coords) >= 2 else zeros
    z_coord = _ensure_column_tensor(spatial_coords[2]) if len(spatial_coords) >= 3 else zeros
    
    device = x_coord.device
    dtype = x_coord.dtype
    kx = torch.as_tensor(float(KX), device=device, dtype=dtype)
    ky = torch.as_tensor(float(KY), device=device, dtype=dtype)
    kz = torch.as_tensor(float(KZ), device=device, dtype=dtype)
    
    phase = kx * x_coord + ky * y_coord + kz * z_coord
    
    # Fallback to fundamental wavelength if wave-vector is zero (e.g., user-specified)
    if torch.allclose(kx.abs() + ky.abs() + kz.abs(), torch.tensor(0.0, device=device, dtype=dtype)):
        fundamental = torch.as_tensor(2 * np.pi / lam, device=device, dtype=dtype)
        phase = fundamental * x_coord
        kx, ky, kz = fundamental, torch.zeros_like(fundamental), torch.zeros_like(fundamental)
    
    return phase, kx, ky, kz, x_coord, y_coord, z_coord


def _coupled_velocity_components(coords, lam, jeans, v_1):
    """
    Generate coupled velocity components from the same wave pattern (supports 1D/2D/3D).
    """
    spatial_coords = _extract_spatial_coords(coords)
    phase, kx, ky, kz, _, _, _ = _compute_wave_phase(spatial_coords, lam)
    dtype = phase.dtype
    device = phase.device
    v_scale = torch.as_tensor(float(v_1), device=device, dtype=dtype)
    
    if lam > jeans:
        wave_field = -v_scale * torch.sin(phase)
    else:
        wave_field = v_scale * torch.cos(phase)
    
    k_mag = torch.sqrt(kx**2 + ky**2 + kz**2)
    if k_mag <= torch.tensor(1e-12, device=device, dtype=dtype):
        vx = wave_field
        vy = torch.zeros_like(wave_field)
        vz = torch.zeros_like(wave_field)
    else:
        inv_mag = 1.0 / k_mag
        vx = wave_field * (kx * inv_mag)
        vy = wave_field * (ky * inv_mag)
        vz = wave_field * (kz * inv_mag)
    
    return vx, vy, vz


def fun_rho_0(rho_1, lam, x):
    """
    Define initial condition for density.
    
    Args:
        rho_1: Perturbation amplitude
        lam: Wavelength
        x: Spatial coordinates [x, y, t] or [x, t]
    
    Returns:
        rho_0: Initial density field
    """
    if str(PERTURBATION_TYPE).lower() == "sinusoidal":
        spatial_coords = _extract_spatial_coords(x)
        phase, *_ = _compute_wave_phase(spatial_coords, lam)
        rho_0 = rho_o + rho_1 * torch.cos(phase)
    else:
        # Power spectrum: uniform initial density
        rho_0 = torch.full_like(x[0], rho_o)
        # Ensure correct shape [N, 1]
        if rho_0.dim() == 1:
            rho_0 = rho_0.unsqueeze(-1)
    
    return rho_0


def fun_vx_0(lam, jeans, v_1, x):
    """
    Initial condition for x-velocity.
    
    Args:
        lam: Wavelength
        jeans: Jeans length
        v_1: Velocity amplitude
        x: Spatial coordinates
    
    Returns:
        vx_0: Initial x-velocity field
    """
    if str(PERTURBATION_TYPE).lower() == "sinusoidal":
        vx, _, _ = _coupled_velocity_components(x, lam, jeans, v_1)
        return vx
    else:
        # Power spectrum case
        return generate_power_spectrum_field(lam, v_1, x, seed=RANDOM_SEED)


def fun_vy_0(lam, jeans, v_1, x):
    """
    Initial condition for y-velocity.
    
    Args:
        lam: Wavelength
        jeans: Jeans length
        v_1: Velocity amplitude
        x: Spatial coordinates
    
    Returns:
        vy_0: Initial y-velocity field
    """
    if str(PERTURBATION_TYPE).lower() == "sinusoidal":
        _, vy, _ = _coupled_velocity_components(x, lam, jeans, v_1)
        return vy
    else:
        # Power spectrum case
        return generate_power_spectrum_field_vy(lam, v_1, x, seed=RANDOM_SEED)


def fun_vz_0(lam, jeans, v_1, x):
    """
    Initial condition for z-velocity (used in 3D sinusoidal runs).
    """
    if str(PERTURBATION_TYPE).lower() == "sinusoidal":
        _, _, vz = _coupled_velocity_components(x, lam, jeans, v_1)
        return vz
    else:
        # Power spectrum setup is currently 2D; default to zero
        return func(x)


def func(x):
    """
    Placeholder function for phi initial condition (zero potential).
    
    Args:
        x: Spatial coordinates
    
    Returns:
        Zero tensor matching the shape of x[0]
    """
    return x[0] * 0
_register_module('core.initial_conditions', ['_compute_wave_phase', '_coupled_velocity_components', '_ensure_column_tensor', '_extract_spatial_coords', '_generate_power_spectrum_fallback', '_interpolate_shared_field', '_shared_vx_interp', '_shared_vy_interp', 'fun_rho_0', 'fun_vx_0', 'fun_vy_0', 'fun_vz_0', 'func', 'generate_power_spectrum_field', 'generate_power_spectrum_field_vy', 'initialize_shared_velocity_fields'])

# ==== Module: core.losses (core/losses.py) ====
from core.data_generator import col_gen
from core.data_generator import diff

import numpy as np

import torch
import torch.nn as nn
from torch.autograd import Variable
from config import cs, const, G, rho_o

class ASTPN(col_gen):
    
    def __init__(self, rmin=[0,0,0,0], rmax=[1,1,1,1], N_0 = 1000, N_b=1000, N_r=3000, dimension=1):
        super().__init__(rmin,rmax, N_0,0,N_r, dimension)  # N_b set to 0 due to hard constraints
        
       
        self.coord_Lx, self.coord_Rx = self.geo_time_coord(option="BC",coordinate=1)
        
        if dimension == 2:
            self.coord_Ly, self.coord_Ry = self.geo_time_coord(option="BC",coordinate=2)

        if dimension == 3:
            self.coord_Ly, self.coord_Ry = self.geo_time_coord(option="BC",coordinate=2)
            self.coord_Lz, self.coord_Rz = self.geo_time_coord(option="BC",coordinate=3)


def pde_residue(colloc, net, dimension = 1):
    
    '''
    This is the main function that returns all the PDE residue
    
    Args:
        colloc: Collocation points
        net: Neural network
        dimension: Spatial dimension (1, 2, or 3)
    '''
    
    return pde_residue_standard(colloc, net, dimension)


def pde_residue_standard(colloc, net, dimension = 1):
    
    '''
    Standard PDE residues (network predicts rho directly)
    '''
    net_outputs = net(colloc)
    
    x = colloc[0]
    
    if dimension == 1:
        t = colloc[1]

    elif dimension == 2:
        y = colloc[1]
        t = colloc[2]

    elif dimension == 3:
        y = colloc[1]
        z = colloc[2]
        t = colloc[3]
    
    rho, vx = net_outputs[:,0:1], net_outputs[:,1:2]

    if dimension == 1:

        phi = net_outputs[:,2:3]

        rho_t = diff(rho,t,order=1)  
        rho_x = diff(rho,x,order=1)

        vx_t = diff(vx, t,order=1)
        vx_x = diff(vx, x,order=1)
        
        phi_x = diff(phi,x,order=1)
        phi_x_x = diff(phi,x,order=2)

    elif dimension == 2:

        vy = net_outputs[:,2:3]
        phi = net_outputs[:,3:4]

        rho_t = diff(rho,t,order=1)  
        rho_x = diff(rho,x,order=1)
        rho_y = diff(rho,y,order=1)

        vx_t = diff(vx, t,order=1)
        vy_t = diff(vy, t,order=1)

        vx_x = diff(vx, x,order=1)
        vx_y = diff(vx, y,order=1)
        vy_x = diff(vy, x,order=1)
        vy_y = diff(vy, y,order=1)
        
        phi_x = diff(phi,x,order=1)
        phi_x_x = diff(phi,x,order=2)

        phi_y = diff(phi,y,order=1)
        phi_y_y = diff(phi,y,order=2)

    elif dimension == 3:
        vy = net_outputs[:,2:3]
        vz = net_outputs[:,3:4]
        phi = net_outputs[:,4:5]

        rho_t = diff(rho,t,order=1)  
        rho_x = diff(rho,x,order=1)
        rho_y = diff(rho,y,order=1)
        rho_z = diff(rho,z,order=1)

        vx_t = diff(vx, t,order=1)
        vy_t = diff(vy, t,order=1)
        vz_t = diff(vz, t,order=1)

        vx_x = diff(vx, x,order=1)
        vy_x = diff(vy, x,order=1)
        vz_x = diff(vz, x,order=1)

        vx_y = diff(vx, y,order=1)
        vy_y = diff(vy, y,order=1)
        vz_y = diff(vz, y,order=1)
        
        vx_z = diff(vx, z,order=1)
        vy_z = diff(vy, z,order=1)
        vz_z = diff(vz, z,order=1)
        
        phi_x = diff(phi,x,order=1)
        phi_x_x = diff(phi,x,order=2)

        phi_y = diff(phi,y,order=1)
        phi_y_y = diff(phi,y,order=2)
    
        phi_z = diff(phi,z,order=1)
        phi_z_z = diff(phi,z,order=2)

    
    ## The residues from the equations

    if dimension == 1:
        rho_r = rho_t + vx * rho_x + rho * vx_x
        vx_r = rho*vx_t + rho*(vx*vx_x) + cs*cs*rho_x +rho*phi_x
        phi_r = phi_x_x - const*(rho - rho_o)

        return rho_r, vx_r, phi_r

    elif dimension == 2:
        rho_r = rho_t + vx * rho_x + vy * rho_y + rho * vx_x + rho * vy_y
        vx_r = rho*vx_t + rho*(vx*vx_x + vy*vx_y) + cs*cs*rho_x + rho*phi_x
        vy_r = rho*vy_t + rho*(vy*vy_y + vx*vy_x) + cs*cs*rho_y + rho*phi_y
        phi_r = phi_x_x + phi_y_y - const*(rho - rho_o)

        return rho_r, vx_r, vy_r, phi_r
    
    elif dimension == 3:
        rho_r = rho_t + vx * rho_x + rho * vx_x + vy *rho_y + rho * vy_y + vz *rho_z +rho * vz_z
        vx_r = rho*vx_t + rho*(vx*vx_x + vy*vx_y+vz*vx_z) + cs*cs*rho_x + rho*phi_x
        vy_r = rho*vy_t + rho*(vy*vy_y + vx*vy_x+vz*vy_z) + cs*cs*rho_y + rho*phi_y
        vz_r = rho*vz_t + rho*(vz*vz_z + vx*vz_x+vy*vz_y) + cs*cs*rho_z + rho*phi_z
        phi_r = phi_x_x + phi_y_y +phi_z_z - const*(rho - rho_o)
        
        return rho_r,vx_r,vy_r,vz_r,phi_r


def poisson_residue_only(colloc, net, dimension=1):
    """
    Compute only the Poisson equation residual: ∇²φ - const*(ρ - ρ₀)
    
    This is used for extra enforcement at t=0 (Option 3: Pure ML approach).
    By evaluating Poisson residual on many t=0 points, we ensure φ is 
    correctly initialized without using numerical solvers.
    
    Args:
        colloc: Collocation points [x, (y), (z), t]
        net: Neural network
        dimension: Spatial dimension (1, 2, or 3)
    
    Returns:
        phi_r: Poisson residual tensor
    """
    net_outputs = net(colloc)
    
    x = colloc[0]
    
    if dimension == 1:
        t = colloc[1]
        phi = net_outputs[:, 2:3]
        phi_x_x = diff(phi, x, order=2)
        
    elif dimension == 2:
        y = colloc[1]
        t = colloc[2]
        phi = net_outputs[:, 3:4]
        phi_x_x = diff(phi, x, order=2)
        phi_y_y = diff(phi, y, order=2)
        
    elif dimension == 3:
        y = colloc[1]
        z = colloc[2]
        t = colloc[3]
        phi = net_outputs[:, 4:5]
        phi_x_x = diff(phi, x, order=2)
        phi_y_y = diff(phi, y, order=2)
        phi_z_z = diff(phi, z, order=2)
    
    # Get density
    rho = net_outputs[:, 0:1]
    
    # Compute Poisson residual
    if dimension == 1:
        phi_r = phi_x_x - const*(rho - rho_o)
    elif dimension == 2:
        phi_r = phi_x_x + phi_y_y - const*(rho - rho_o)
    elif dimension == 3:
        phi_r = phi_x_x + phi_y_y + phi_z_z - const*(rho - rho_o)
    
    return phi_r


class XPINN_Loss:
    """
    XPINN Loss computation for domain decomposition.
    
    Computes:
    - PDE residual loss per subdomain
    - Initial condition loss per subdomain
    - Periodic BC loss (only exterior boundaries)
    - Interface continuity losses (solution + residual)
    """
    
    def __init__(self, rmin, rmax, dimension=2):
        """
        Initialize XPINN loss computer.
        
        Args:
            rmin: List of minimum values [xmin, ymin, tmin] (for 2D)
            rmax: List of maximum values [xmax, ymax, tmax] (for 2D)
            dimension: Spatial dimension (default 2)
        """
        self.rmin = rmin
        self.rmax = rmax
        self.dimension = dimension
        
        # Import config values
        from config import (INTERFACE_SOLUTION_WEIGHT, INTERFACE_RESIDUAL_WEIGHT,
                           INTERFACE_SOLUTION_COMPONENTS)
        self.interface_solution_weight = INTERFACE_SOLUTION_WEIGHT
        self.interface_residual_weight = INTERFACE_RESIDUAL_WEIGHT
        self.interface_components = INTERFACE_SOLUTION_COMPONENTS
        
        # Component name to index mapping
        self.component_map = {'rho': 0, 'vx': 1, 'vy': 2, 'phi': 3}
    
    def compute_pde_loss(self, colloc, net):
        """
        Compute PDE residual loss for a subdomain.
        
        Args:
            colloc: Collocation points [x, y, t]
            net: Neural network for this subdomain
        
        Returns:
            PDE residual loss (scalar)
        """
        residuals = pde_residue(colloc, net, dimension=self.dimension)
        
        # Sum squared residuals
        loss = sum(torch.mean(r**2) for r in residuals)
        return loss
    
    def compute_ic_loss(self, colloc_ic, net, ic_functions, cached_ic=None):
        """
        Compute initial condition loss for a subdomain.
        
        Args:
            colloc_ic: Initial condition collocation points [x, y, t=0]
            net: Neural network for this subdomain
            ic_functions: Dictionary of initial condition functions
                          {'rho': func, 'vx': func, 'vy': func, 'phi': func}
            cached_ic: Precomputed IC values (optional)
        
        Returns:
            IC loss (scalar)
        """
        # Get network predictions at t=0
        u_pred = net(colloc_ic)
        
        # Use cached IC values if available, otherwise compute them
        if cached_ic is not None:
            ic_rho = cached_ic['rho']
            ic_vx = cached_ic['vx']
            ic_vy = cached_ic['vy']
            ic_phi = cached_ic['phi']
        else:
            # Compute initial conditions
            ic_rho = ic_functions['rho'](colloc_ic)
            ic_vx = ic_functions['vx'](colloc_ic)
            ic_vy = ic_functions['vy'](colloc_ic)
            ic_phi = ic_functions['phi'](colloc_ic)
        
        # Compute MSE for each component
        loss_rho = torch.mean((u_pred[:, 0:1] - ic_rho)**2)
        loss_vx = torch.mean((u_pred[:, 1:2] - ic_vx)**2)
        loss_vy = torch.mean((u_pred[:, 2:3] - ic_vy)**2)
        loss_phi = torch.mean((u_pred[:, 3:4] - ic_phi)**2)
        
        total_ic_loss = loss_rho + loss_vx + loss_vy + loss_phi
        return total_ic_loss
    
    def compute_interface_solution_loss(self, colloc_interface, net1, net2, grad_to='both'):
        """
        Compute solution continuity loss at interface.
        
        Enforces: u_avg = (u1 + u2)/2 for both networks.
        Minimizes: |u1 - u_avg|^2 + |u2 - u_avg|^2
        
        Args:
            colloc_interface: Interface collocation points [x, y, t]
            net1, net2: Neural networks for adjacent subdomains
            grad_to: 'both' (default), 'net1', or 'net2' - controls which network receives gradients
        
        Returns:
            Solution continuity loss (scalar)
        """
        # Move interface points to each network's device
        device1 = next(net1.parameters()).device
        device2 = next(net2.parameters()).device
        
        colloc_interface_1 = [t.to(device1) for t in colloc_interface]
        colloc_interface_2 = [t.to(device2) for t in colloc_interface]
        
        # Get predictions from both networks at interface
        u1 = net1(colloc_interface_1)
        u2 = net2(colloc_interface_2)
        
        # Detach neighbor network BEFORE any device transfers to avoid graph sharing
        if grad_to == 'net1':
            u2 = u2.detach()
        elif grad_to == 'net2':
            u1 = u1.detach()
        
        # Compute loss on the device of the network we're training
        if grad_to == 'net2':
            # Backprop only to net2; compute on device2
            # u1 is already detached, so moving it won't create gradients
            u1_on_device2 = u1.to(device2)
            u_avg = (u1_on_device2 + u2) / 2.0
            loss = 0.0
            for comp_name in self.interface_components:
                if comp_name in self.component_map:
                    idx = self.component_map[comp_name]
                    if idx < u2.shape[1]:
                        u2_comp = u2[:, idx:idx+1]
                        u_avg_comp = u_avg[:, idx:idx+1]
                        loss += torch.mean((u2_comp - u_avg_comp)**2)
        else:
            # Backprop to net1 (or both); compute on device1
            # u2 is already detached, so moving it won't create gradients
            u2_on_device1 = u2.to(device1)
            u_avg = (u1 + u2_on_device1) / 2.0
            loss = 0.0
            for comp_name in self.interface_components:
                if comp_name in self.component_map:
                    idx = self.component_map[comp_name]
                    if idx < u1.shape[1]:
                        u1_comp = u1[:, idx:idx+1]
                        u_avg_comp = u_avg[:, idx:idx+1]
                        loss += torch.mean((u1_comp - u_avg_comp)**2)
                        if grad_to == 'both':
                            u2_comp = u2_on_device1[:, idx:idx+1]
                            loss += torch.mean((u2_comp - u_avg_comp)**2)
        
        return self.interface_solution_weight * loss
    
    def compute_interface_residual_loss(self, colloc_interface, net1, net2, grad_to='both'):
        """
        Compute residual continuity loss at interface.
        
        Enforces: R1(interface) = R2(interface)
        
        Args:
            colloc_interface: Interface collocation points [x, y, t]
            net1, net2: Neural networks for adjacent subdomains
            grad_to: 'both' (default), 'net1', or 'net2' - controls which network receives gradients
        
        Returns:
            Residual continuity loss (scalar)
        """
        # Move interface points to each network's device
        device1 = next(net1.parameters()).device
        device2 = next(net2.parameters()).device
        
        colloc_interface_1 = [t.to(device1) for t in colloc_interface]
        colloc_interface_2 = [t.to(device2) for t in colloc_interface]
        
        # Compute PDE residuals from both networks at interface
        residuals1 = pde_residue(colloc_interface_1, net1, dimension=self.dimension)
        residuals2 = pde_residue(colloc_interface_2, net2, dimension=self.dimension)
        
        # Enforce residual matching for all PDE components
        loss = 0.0
        if grad_to == 'net2':
            # Backprop only to net2; compute on device2
            for r1, r2 in zip(residuals1, residuals2):
                r1_detached = r1.detach().to(device2)
                loss += torch.mean((r2 - r1_detached)**2)
        elif grad_to == 'net1':
            # Backprop only to net1; compute on device1
            for r1, r2 in zip(residuals1, residuals2):
                r2_detached = r2.detach().to(device1)
                loss += torch.mean((r1 - r2_detached)**2)
        else:
            # Backprop to both (original behavior); compute on device1
            for r1, r2 in zip(residuals1, residuals2):
                r2_on_device1 = r2.to(device1)
                loss += torch.mean((r1 - r2_on_device1)**2)
        
        return self.interface_residual_weight * loss
    
    # NOTE: Periodic boundary conditions are enforced via periodic feature encoding
    # (n_harmonics in _periodic_features method of PINN class), NOT via loss term.
    # This is a hard constraint approach where the network architecture guarantees periodicity.
    
    def compute_total_loss(self, nets, subdomain_collocs, interface_collocs, 
                          subdomain_ic_collocs, ic_functions, interfaces, 
                          exterior_boundaries, cached_ic_values=None):
        """
        Compute total XPINN loss aggregating all components.
        
        Args:
            nets: List of neural networks (one per subdomain)
            subdomain_collocs: List of subdomain collocation points
            interface_collocs: Dict mapping interface tuple to collocation points
            subdomain_ic_collocs: List of IC collocation points per subdomain
            ic_functions: Initial condition functions
            interfaces: List of interface tuples (subdomain_i, subdomain_j, type, pos)
            exterior_boundaries: Dict mapping subdomain_idx to boundary info
            cached_ic_values: Precomputed IC values (list of dicts per subdomain, optional)
        
        Returns:
            Tuple (total_loss, loss_dict) where loss_dict contains component losses
        """
        if cached_ic_values is None:
            cached_ic_values = [None] * len(nets)
            
        # Initialize loss dict on device 0 (or appropriate device for single GPU)
        device = 'cuda:0' if len(nets) > 1 else next(nets[0].parameters()).device
        loss_dict = {
            'pde': torch.tensor(0.0, device=device),
            'ic': torch.tensor(0.0, device=device),
            'interface_solution': torch.tensor(0.0, device=device),
            'interface_residual': torch.tensor(0.0, device=device)
        }
        
        # PDE and IC losses for each subdomain
        for i, (net, colloc, colloc_ic) in enumerate(zip(nets, subdomain_collocs, subdomain_ic_collocs)):
            # Compute losses on the device where the network lives
            pde_loss = self.compute_pde_loss(colloc, net)
            ic_loss = self.compute_ic_loss(colloc_ic, net, ic_functions, cached_ic_values[i])
            
            # Move losses to device 0 for aggregation (or keep on same device if single GPU)
            if len(nets) > 1:  # Multi-GPU case
                pde_loss = pde_loss.to(device)
                ic_loss = ic_loss.to(device)
            
            loss_dict['pde'] += pde_loss
            loss_dict['ic'] += ic_loss
        
        # Interface losses
        for interface in interfaces:
            subdomain_i, subdomain_j, _, _ = interface
            interface_key = (subdomain_i, subdomain_j)
            
            if interface_key in interface_collocs:
                colloc_interface = interface_collocs[interface_key]
                net1 = nets[subdomain_i]
                net2 = nets[subdomain_j]
                
                # Compute interface losses
                sol_loss = self.compute_interface_solution_loss(colloc_interface, net1, net2)
                res_loss = self.compute_interface_residual_loss(colloc_interface, net1, net2)
                
                # Move losses to device 0 for aggregation (or keep on same device if single GPU)
                if len(nets) > 1:  # Multi-GPU case
                    sol_loss = sol_loss.to(device)
                    res_loss = res_loss.to(device)
                
                loss_dict['interface_solution'] += sol_loss
                loss_dict['interface_residual'] += res_loss
        
        # NOTE: Periodic BC NOT included here - enforced via periodic feature encoding (harmonics)
        # in the PINN architecture, which is a hard constraint approach.
        
        # Total loss
        total_loss = sum(loss_dict.values())
        
        return total_loss, loss_dict
_register_module('core.losses', ['ASTPN', 'XPINN_Loss', 'pde_residue', 'pde_residue_standard', 'poisson_residue_only'])

# ==== Module: core.model_architecture (core/model_architecture.py) ====
import numpy as np

import torch
import torch.nn as nn
#from torch.autograd import Variable
from config import rho_o, num_neurons, num_layers, PERTURBATION_TYPE, DEFAULT_ACTIVATION, STARTUP_DT, USE_PARAMETERIZATION

class Sin(nn.Module):
    def forward(self, input):
        return torch.sin(input)


def get_activation(activation_type):
    """
    Factory function to create activation function instances.
    
    Args:
        activation_type: String identifier ('sin', 'tanh', 'relu', 'elu')
    
    Returns:
        nn.Module activation function
    """
    activation_type = activation_type.lower()
    if activation_type == 'sin':
        return Sin()
    elif activation_type == 'tanh':
        return nn.Tanh()
    elif activation_type == 'relu':
        return nn.ReLU()
    elif activation_type == 'elu':
        return nn.ELU()
    else:
        raise ValueError(f"Unknown activation type: {activation_type}. Choose from 'sin', 'tanh', 'relu', 'elu'.")

class PINN(nn.Module):
    def __init__(self, num_neurons=num_neurons, num_layers=num_layers, n_harmonics=1, activation_type=DEFAULT_ACTIVATION):
        super(PINN, self).__init__()
        self.num_neurons = num_neurons
        self.n_harmonics = n_harmonics
        self.num_layers = max(2, int(num_layers))  # total Linear layers including output
        self.activation_type = activation_type
        
        # Domain extents for periodic embeddings (set via set_domain)
        self.xmin = None
        self.xmax = None
        self.ymin = None
        self.ymax = None
        self.zmin = None
        self.zmax = None
    
    # Helper to build a branch with dynamic depth
        def _make_branch(in_dim, out_dim):
            layers = []
            # First layer
            layers.append(nn.Linear(in_dim, self.num_neurons))
            # Hidden layers: total linear layers = self.num_layers; we already added 1; 
            # add (self.num_layers - 2) hidden Linear blocks with activations after each
            for _ in range(self.num_layers - 2):
                layers.append(get_activation(self.activation_type))
                layers.append(nn.Linear(self.num_neurons, self.num_neurons))
            # Activation before output if there is at least one hidden block
            if self.num_layers > 2:
                layers.append(get_activation(self.activation_type))
            # Output layer
            layers.append(nn.Linear(self.num_neurons, out_dim))
            return nn.Sequential(*layers)

    # 1D branch (periodic x features + t)
        in_dim_1d = 2*self.n_harmonics + 1
        self.branch_1d = _make_branch(in_dim_1d, 3)
        
    # 2D branch (periodic x,y features + t)
        in_dim_2d = 4*self.n_harmonics + 1
        self.branch_2d = _make_branch(in_dim_2d, 4)
        
    # 3D branch (periodic x,y,z features + t)
        in_dim_3d = 6*self.n_harmonics + 1
        self.branch_3d = _make_branch(in_dim_3d, 5)


    def set_domain(self, rmin, rmax, dimension):
        # rmin/rmax exclude time; follow ASTPN usage
        if dimension >= 1:
            self.xmin, self.xmax = float(rmin[0]), float(rmax[0])
        if dimension >= 2:
            self.ymin, self.ymax = float(rmin[1]), float(rmax[1])
        if dimension >= 3:
            self.zmin, self.zmax = float(rmin[2]), float(rmax[2])

    def _periodic_features(self, u, umin, umax):
        # u is [N,1]
        L = umax - umin
        theta = 2*np.pi*(u - umin)/L
        features = []

        for k in range(1, self.n_harmonics+1):
            
            scale = 1.0 / np.sqrt(k)

            features.append(scale * torch.sin(k*theta))
            features.append(scale * torch.cos(k*theta))

        return torch.cat(features, dim=1) if len(features) > 0 else u

    def _prepare_coordinate_features(self, X):
        """
        Prepare periodic features for all spatial coordinates.
        
        Args:
            X: List of coordinates [x, ...spatial..., t]
        
        Returns:
            Tuple (features, t_tensor, dimension)
        """
        x, t = X[0], X[-1]
        x = x.unsqueeze(-1) if x.dim() == 1 else x
        t = t.unsqueeze(-1) if t.dim() == 1 else t
        dimension = len(X)
        
        if dimension == 2:
            if self.xmin is None or self.xmax is None:
                raise RuntimeError("Domain not set: call net.set_domain for dimension=1")
            x_feat = self._periodic_features(x, self.xmin, self.xmax)
            features = torch.cat([x_feat, t], dim=1)
        
        elif dimension == 3:
            if self.xmin is None or self.xmax is None or self.ymin is None or self.ymax is None:
                raise RuntimeError("Domain not set: call net.set_domain for dimension=2")
            y = X[1].unsqueeze(-1) if X[1].dim() == 1 else X[1]
            x_feat = self._periodic_features(x, self.xmin, self.xmax)
            y_feat = self._periodic_features(y, self.ymin, self.ymax)
            features = torch.cat([x_feat, y_feat, t], dim=1)
        
        elif dimension == 4:
            if (self.xmin is None or self.xmax is None or
                self.ymin is None or self.ymax is None or
                self.zmin is None or self.zmax is None):
                raise RuntimeError("Domain not set: call net.set_domain for dimension=3")
            y = X[1].unsqueeze(-1) if X[1].dim() == 1 else X[1]
            z = X[2].unsqueeze(-1) if X[2].dim() == 1 else X[2]
            x_feat = self._periodic_features(x, self.xmin, self.xmax)
            y_feat = self._periodic_features(y, self.ymin, self.ymax)
            z_feat = self._periodic_features(z, self.zmin, self.zmax)
            features = torch.cat([x_feat, y_feat, z_feat, t], dim=1)
        
        else:
            raise ValueError(f"Expected len(X) in [2, 3, 4] but got {dimension}")
        
        return features, t, dimension
    
    def _apply_density_constraint(self, outputs, t):
        """
        Apply hard density constraint with causality enforcement for power spectrum perturbations.
        
        For power spectrum (non-sinusoidal):
        - For t < STARTUP_DT: Density is frozen at ρ₀ (causality - information hasn't propagated)
        - For t >= STARTUP_DT: Density evolves based on USE_PARAMETERIZATION:
          * "exponential": ρ = ρ₀ × exp(clamp((t - STARTUP_DT) × ρ̂, -10, 10))
            (ensures strictly positive density)
          * "linear": ρ = ρ₀ + (t - STARTUP_DT) × ρ̂
            (linear growth from initial condition)
          * "none": ρ = ρ̂
            (direct network prediction, no transformation)
        
        The causality constraint (STARTUP_DT) is enforced for all parameterizations.
        This ensures density remains at initial conditions until information has had time
        to propagate across the domain (finite signal speed).
        
        For sinusoidal: No constraint (returns as-is).
        
        Args:
            outputs: Raw network outputs [ρ̂, vx, vy?, vz?, phi]
            t: Time tensor
        
        Returns:
            Modified outputs with density constraint applied [ρ, vx, vy?, vz?, phi]
        """
        if str(PERTURBATION_TYPE).lower() == "sinusoidal":
            return outputs
        
        # Causality constraint for power spectrum:
        # Density frozen at ρ₀ for t < STARTUP_DT (information propagation delay)
        rho_hat = outputs[:, 0:1]
        other = outputs[:, 1:]
        
        # Create mask for causality: 1.0 where t >= STARTUP_DT, 0.0 where t < STARTUP_DT
        causal_mask = (t >= STARTUP_DT).float()
        
        # Effective time: zero for t < STARTUP_DT, (t - STARTUP_DT) for t >= STARTUP_DT
        t_effective = torch.clamp(t - STARTUP_DT, min=0.0)
        
        # Apply parameterization based on config
        parameterization = str(USE_PARAMETERIZATION).lower()
        
        if parameterization == "exponential":
            # Exponential parameterization: ρ = ρ₀ * exp(t_eff * ρ̂)
            # For t < STARTUP_DT: t_eff = 0, so exp(0) = 1, thus ρ = ρ₀
            # For t >= STARTUP_DT: ρ evolves exponentially
            rho = rho_o * torch.exp(torch.clamp(t_effective * rho_hat, min=-10, max=10))
            
        elif parameterization == "linear":
            # Linear parameterization: ρ = ρ₀ + t_eff * ρ̂
            # For t < STARTUP_DT: t_eff = 0, so ρ = ρ₀
            # For t >= STARTUP_DT: ρ grows linearly
            rho = rho_o + t_effective * rho_hat
            
        elif parameterization == "none":
            # No parameterization: direct prediction with causality enforcement
            # For t < STARTUP_DT: ρ = ρ₀ (frozen at initial condition)
            # For t >= STARTUP_DT: ρ = ρ̂ (network output directly)
            rho = causal_mask * rho_hat + (1 - causal_mask) * rho_o
            
        else:
            raise ValueError(f"Invalid USE_PARAMETERIZATION: '{USE_PARAMETERIZATION}'. "
                           f"Choose from: 'exponential', 'linear', 'none'")
        
        return torch.cat([rho, other], dim=1)
    
    def forward(self, X):
        """
        Forward pass of PINN.
        
        Args:
            X: List of coordinates [x, ...spatial..., t]
        
        Returns:
            Network predictions [rho, vx, vy?, vz?, phi]
        """
        features, t, dimension = self._prepare_coordinate_features(X)
        
        # Select appropriate branch based on dimension
        if dimension == 2:
            outputs = self.branch_1d(features)
        elif dimension == 3:
            outputs = self.branch_2d(features)
        elif dimension == 4:
            outputs = self.branch_3d(features)
        else:
            raise ValueError(f"Unexpected dimension: {dimension}")
        
        return self._apply_density_constraint(outputs, t)
        
def init_weights(m):
    if isinstance(m, nn.Linear):
        torch.nn.init.xavier_uniform_(m.weight)
        m.bias.data.fill_(0.01)
_register_module('core.model_architecture', ['PINN', 'Sin', 'get_activation', 'init_weights'])

# ==== Module: methods.causal_training (methods/causal_training.py) ====
"""
Causal Training Module for Physics-Informed Neural Networks

This module provides infrastructure for causal training with temporal curriculum
and adaptive/static weighting schemes. Similar to xpinn_decomposition.py structure.

Key Components:
- ResidualTracker: Tracks residuals across time bins for adaptive weighting
- CausalTrainer: Orchestrates the complete causal training workflow
- Helper functions for window scheduling, weight computation, etc.
"""

import numpy as np
import torch


class ResidualTracker:
    """
    Tracks cumulative residuals across time bins for adaptive causal weighting.
    Implements w_i = exp(-epsilon * Σ_{k=1}^{i-1} L_r(t_k, θ))
    """
    def __init__(self, t_min, t_max, num_bins, epsilon, device='cuda'):
        """
        Args:
            t_min: Minimum time value
            t_max: Maximum time value
            num_bins: Number of time bins for tracking residuals
            epsilon: Causality parameter (controls weight suppression strength)
            device: PyTorch device
        """
        self.t_min = t_min
        self.t_max = t_max
        self.num_bins = num_bins
        self.epsilon = epsilon
        self.device = device
        
        # Bin edges for time discretization
        self.bin_edges = torch.linspace(t_min, t_max, num_bins + 1, device=device)
        self.bin_width = (t_max - t_min) / num_bins
        
        # Cumulative residuals per bin (initialized to zero)
        self.cumulative_residuals = torch.zeros(num_bins, device=device)
        
        # Counter for number of updates per bin (for averaging)
        self.update_counts = torch.zeros(num_bins, device=device)
    
    def get_bin_indices(self, t_values):
        """Get bin indices for given time values."""
        t_flat = t_values.flatten()
        bin_idx = ((t_flat - self.t_min) / self.bin_width).long()
        return torch.clamp(bin_idx, 0, self.num_bins - 1)
    
    def update_residuals(self, t_values, residuals):
        """
        Update cumulative residuals for time bins based on current batch.
        
        Args:
            t_values: Time values [N, 1]
            residuals: PDE residuals [N, 1] or list of residuals
        """
        # Convert residuals to single scalar per point if it's a list
        if isinstance(residuals, (list, tuple)):
            total_residual = sum(r.flatten() ** 2 for r in residuals)
            residual_values = torch.sqrt(total_residual)
        else:
            residual_values = residuals.flatten().abs()
        
        bin_idx = self.get_bin_indices(t_values)
        
        # Vectorized accumulation using bincount
        bin_sums = torch.bincount(bin_idx, weights=residual_values, minlength=self.num_bins)
        bin_counts = torch.bincount(bin_idx, minlength=self.num_bins).to(bin_sums.dtype)
        
        self.cumulative_residuals += bin_sums.detach()
        self.update_counts += bin_counts.detach()
    
    def get_adaptive_weights(self, t_values):
        """
        Compute adaptive causal weights based on cumulative past residuals.
        w_i = exp(-epsilon * Σ_{k=1}^{i-1} L_r(t_k))
        
        Args:
            t_values: Time values [N, 1]
        
        Returns:
            Weights [N, 1]
        """
        eps = 1e-12
        bin_idx = self.get_bin_indices(t_values)
        
        # Compute average residual per bin (point-averaged)
        avg_residuals = self.cumulative_residuals / (self.update_counts + eps)
        
        # Normalize by early-time scale (bin 0) to keep magnitude stable
        ref_scale = avg_residuals[0].clamp_min(eps)
        avg_residuals_norm = avg_residuals / ref_scale
        
        # Compute cumulative sum of normalized average residuals
        cumsum_avg = torch.cumsum(avg_residuals_norm, dim=0)
        
        # For bin i, we want sum from bins 0 to i-1, so shift cumsum by 1
        cumsum_shifted = torch.cat([torch.zeros(1, device=self.device), cumsum_avg[:-1]], dim=0)
        
        # Gather the appropriate cumulative sum for each point based on its bin
        bin_idx_flat = bin_idx.clamp(min=0, max=self.num_bins-1)
        past_residual_sum = cumsum_shifted[bin_idx_flat]
        
        # Apply exponential suppression with floor to prevent starving later times
        weights = torch.exp(-self.epsilon * past_residual_sum).clamp_min(0.02)
        
        return weights.unsqueeze(-1) if weights.dim() == 1 else weights
    
    def reset(self):
        """Reset cumulative residuals and counts."""
        self.cumulative_residuals.zero_()
        self.update_counts.zero_()
    
    def get_stats(self):
        """Get current statistics for logging."""
        avg_residuals = torch.where(
            self.update_counts > 0,
            self.cumulative_residuals / self.update_counts,
            torch.zeros_like(self.cumulative_residuals)
        )
        return {
            'cumulative': self.cumulative_residuals.cpu().numpy(),
            'counts': self.update_counts.cpu().numpy(),
            'average': avg_residuals.cpu().numpy()
        }


def compute_causal_weights_static(t_values, gamma):
    """
    Compute static causal weights: w(t) = exp(-gamma * t)
    
    Args:
        t_values: Time values tensor [N, 1]
        gamma: Exponential decay parameter
    
    Returns:
        Weights [N, 1]
    """
    if gamma == 0.0:
        return torch.ones_like(t_values)
    return torch.exp(-gamma * t_values)


def generate_temporal_windows(schedule, num_windows, tmin, tmax, startup_dt, custom_windows=None):
    """
    Generate temporal window boundaries for curriculum training.
    
    Args:
        schedule: 'linear' or 'custom'
        num_windows: Number of windows (ignored if schedule='custom')
        tmin: Minimum time
        tmax: Maximum time  
        startup_dt: Startup time offset
        custom_windows: List of [t_min, t_max] pairs for custom schedule
    
    Returns:
        List of (t_min, t_max) tuples
    """
    if schedule == "custom":
        if custom_windows is None:
            raise ValueError("custom_windows required for custom schedule")
        return [(float(w[0]), float(w[1])) for w in custom_windows]
    elif schedule == "linear":
        # Linear progression from startup_dt to tmax
        t_start = max(tmin, startup_dt)
        window_times = np.linspace(t_start, tmax, num_windows + 1)
        return [(float(window_times[i]), float(window_times[i+1])) for i in range(num_windows)]
    else:
        raise ValueError(f"Unknown schedule: {schedule}")


def compute_epsilon_for_window(window_idx, num_windows, epsilon_min, epsilon_max, 
                                epsilon_base, epsilon_floor, use_annealing):
    """
    Compute epsilon value for current window in adaptive mode.
    
    Args:
        window_idx: Current window index (0-based)
        num_windows: Total number of windows
        epsilon_min: Minimum epsilon (for annealing)
        epsilon_max: Maximum epsilon (for annealing)
        epsilon_base: Base epsilon value (for linear decay)
        epsilon_floor: Floor epsilon value (for linear decay)
        use_annealing: Whether to use automatic annealing
    
    Returns:
        epsilon value for this window
    """
    if use_annealing:
        # Automatic interpolation between MIN and MAX (ensures monotonic increase)
        progress = window_idx / max(1, num_windows - 1)
        return epsilon_min + (epsilon_max - epsilon_min) * progress
    else:
        # Linear decay (original method): strong early → moderate late
        return epsilon_floor + (epsilon_base - epsilon_floor) * (1.0 - window_idx / max(1, num_windows - 1))


def compute_gamma_for_window(window_idx, num_windows, gamma_max, gamma_min):
    """
    Compute gamma value for current window in static mode.
    
    Args:
        window_idx: Current window index (0-based)
        num_windows: Total number of windows
        gamma_max: Maximum gamma value (early windows)
        gamma_min: Minimum gamma value (final window)
    
    Returns:
        gamma value for this window
    """
    # Linear decay from gamma_max to gamma_min
    progress = window_idx / max(1, num_windows - 1)
    return gamma_max * (1.0 - progress) + gamma_min * progress


class CausalTrainer:
    """
    Orchestrates causal training with temporal curriculum and adaptive/static weighting.
    """
    
    def __init__(self, model, net, optimizer, optimizerL, mse_cost_function,
                 train_func, config, device):
        """
        Args:
            model: ASTPN model for collocation generation
            net: Neural network
            optimizer: Adam optimizer
            optimizerL: LBFGS optimizer
            mse_cost_function: Loss function
            train_func: Training function (from solver.py)
            config: Dictionary with all causal config parameters
            device: PyTorch device
        """
        self.model = model
        self.net = net
        self.optimizer = optimizer
        self.optimizerL = optimizerL
        self.mse_cost_function = mse_cost_function
        self.train_func = train_func
        self.config = config
        self.device = device
        
        # Initialize residual tracker for adaptive mode
        self.residual_tracker = None
        if config['weighting_mode'] == 'adaptive':
            t_start = max(config['tmin'], config['startup_dt'])
            self.residual_tracker = ResidualTracker(
                t_min=t_start,
                t_max=config['tmax'],
                num_bins=config['num_time_bins'],
                epsilon=config['epsilon'],
                device=device
            )
    
    def train_with_curriculum(self, collocation_IC, **train_kwargs):
        """
        Train with temporal curriculum (progressive time windows).
        
        Args:
            collocation_IC: Initial condition collocation points
            **train_kwargs: Additional kwargs for train function (rho_1, lam, etc.)
        
        Returns:
            Trained network
        """
        cfg = self.config
        use_restarts = cfg['use_restarts']
        
        # Generate temporal windows
        windows = generate_temporal_windows(
            schedule=cfg['window_schedule'],
            num_windows=cfg['num_windows'],
            tmin=cfg['tmin'],
            tmax=cfg['tmax'],
            startup_dt=cfg['startup_dt'],
            custom_windows=cfg['custom_windows']
        )
        
        # Compute iterations per window
        adam_per_window = cfg['adam_per_window'] or (cfg['iteration_adam'] // cfg['num_windows'])
        lbfgs_per_window = cfg['lbfgs_per_window'] or (cfg['iteration_lbfgs'] // cfg['num_windows'])
        
        print(f"Training schedule: {len(windows)} windows, {adam_per_window} Adam + {lbfgs_per_window} LBFGS per window")
        
        # Train on each window
        for window_idx, (t_window_min, t_window_max) in enumerate(windows):
            print(f"\n{'='*60}")
            print(f"Window {window_idx + 1}/{len(windows)}: t in [{t_window_min:.3f}, {t_window_max:.3f}]")
            print(f"{'='*60}")
            
            # Compute causal parameters for this window
            if cfg['weighting_mode'] == 'static':
                causal_gamma = compute_gamma_for_window(
                    window_idx, len(windows), cfg['gamma_max'], cfg['gamma_min']
                )
                print(f"  Static weighting: gamma = {causal_gamma:.4f}")
                causal_mode = 'static'
            else:  # adaptive
                causal_gamma = 0.0
                causal_mode = 'adaptive'
                
                # Update epsilon for this window
                if self.residual_tracker is not None:
                    eps_k = compute_epsilon_for_window(
                        window_idx, len(windows),
                        cfg['epsilon_min'], cfg['epsilon_max'],
                        cfg['epsilon'], cfg['epsilon_floor'],
                        cfg['use_epsilon_annealing']
                    )
                    self.residual_tracker.epsilon = eps_k
                    if cfg['use_epsilon_annealing']:
                        print(f"  Adaptive weighting: epsilon = {eps_k:.3f} (annealed)")
                    else:
                        print(f"  Adaptive weighting: epsilon = {eps_k:.3f} (linear decay)")
            
            # Update model's temporal bounds for this window
            if use_restarts and window_idx > 0:
                # Restart marching: train only in current window [t_k, t_{k+1}]
                t_start = t_window_min
            else:
                # Expanding windows: train from t=0 to current t_max
                t_start = max(cfg['tmin'], cfg['startup_dt'])
            
            # Build rmin/rmax based on spatial dimension (2D or 3D)
            dimension = cfg.get('dimension', 2)  # Default to 2D for backward compatibility
            if dimension == 3:
                self.model.rmin = [cfg['xmin'], cfg['ymin'], cfg['zmin'], t_start]
                self.model.rmax = [cfg['xmax'], cfg['ymax'], cfg['zmax'], t_window_max]
            else:  # 2D or 1D
                self.model.rmin = [cfg['xmin'], cfg['ymin'], t_start]
                self.model.rmax = [cfg['xmax'], cfg['ymax'], t_window_max]
            
            # Regenerate domain collocation for this window
            collocation_domain_window = self.model.geo_time_coord(option="Domain")
            
            # Train on this window
            self.train_func(
                net=self.net,
                model=self.model,
                collocation_domain=collocation_domain_window,
                collocation_IC=collocation_IC,
                optimizer=self.optimizer,
                optimizerL=self.optimizerL,
                closure=None,
                mse_cost_function=self.mse_cost_function,
                iteration_adam=adam_per_window,
                iterationL=lbfgs_per_window,
                device=self.device,
                causal_gamma=causal_gamma,
                causal_mode=causal_mode,
                residual_tracker=self.residual_tracker,
                window_idx=window_idx,
                **train_kwargs
            )
        
        # Restore full time/space range for final evaluation/plotting
        dimension = cfg.get('dimension', 2)  # Default to 2D for backward compatibility
        if dimension == 3:
            self.model.rmin = [cfg['xmin'], cfg['ymin'], cfg['zmin'], cfg['tmin']]
            self.model.rmax = [cfg['xmax'], cfg['ymax'], cfg['zmax'], cfg['tmax']]
        else:  # 2D or 1D
            self.model.rmin = [cfg['xmin'], cfg['ymin'], cfg['tmin']]
            self.model.rmax = [cfg['xmax'], cfg['ymax'], cfg['tmax']]
        
        if use_restarts:
            print(f"\nCausal training completed (restart marching). Final time range: [{cfg['tmin']}, {cfg['tmax']}]")
        else:
            print(f"\nCausal training completed (expanding windows). Final time range: [{cfg['tmin']}, {cfg['tmax']}]")
        
        return self.net
    
    def train_without_curriculum(self, collocation_IC, **train_kwargs):
        """
        Train on full domain with adaptive weighting (no temporal windows).
        
        Args:
            collocation_IC: Initial condition collocation points
            **train_kwargs: Additional kwargs for train function
        
        Returns:
            Trained network
        """
        cfg = self.config
        
        print("Training on full temporal domain with adaptive weighting...")
        
        # Generate full domain collocation
        collocation_domain = self.model.geo_time_coord(option="Domain")
        
        # Train with adaptive weighting
        self.train_func(
            net=self.net,
            model=self.model,
            collocation_domain=collocation_domain,
            collocation_IC=collocation_IC,
            optimizer=self.optimizer,
            optimizerL=self.optimizerL,
            closure=None,
            mse_cost_function=self.mse_cost_function,
            iteration_adam=cfg['iteration_adam'],
            iterationL=cfg['iteration_lbfgs'],
            device=self.device,
            causal_gamma=0.0,  # Not used in adaptive mode
            causal_mode=cfg['weighting_mode'],
            residual_tracker=self.residual_tracker,
            window_idx=None,
            **train_kwargs
        )
        
        print(f"\nCausal training completed (full domain)")
        
        return self.net
_register_module('methods.causal_training', ['CausalTrainer', 'ResidualTracker', 'compute_causal_weights_static', 'compute_epsilon_for_window', 'compute_gamma_for_window', 'generate_temporal_windows'])

# ==== Module: methods.xpinn_decomposition (methods/xpinn_decomposition.py) ====
"""
XPINN Domain Decomposition Utilities

Provides functions for subdomain boundary calculation, interface identification,
and collocation point generation for XPINN-style domain decomposition.
"""

import numpy as np
import torch


def get_num_subdomains(nx_sub, ny_sub):
    """
    Calculate total number of subdomains.
    
    Args:
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        Total number of subdomains
    """
    return nx_sub * ny_sub


def subdomain_idx_to_grid(idx, nx_sub, ny_sub):
    """
    Convert linear subdomain index to (i, j) grid position.
    
    Args:
        idx: Linear subdomain index (0 to nx_sub*ny_sub-1)
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        Tuple (i, j) representing grid position where:
        - i is x-direction index (0 to nx_sub-1)
        - j is y-direction index (0 to ny_sub-1)
    """
    i = idx // ny_sub
    j = idx % ny_sub
    return (i, j)


def get_subdomain_bounds(subdomain_idx, xmin, xmax, ymin, ymax, nx_sub, ny_sub):
    """
    Compute spatial boundaries for a given subdomain.
    
    Args:
        subdomain_idx: Linear subdomain index
        xmin, xmax: Global domain x-bounds
        ymin, ymax: Global domain y-bounds
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        Tuple (x_min, x_max, y_min, y_max) for the subdomain
    """
    i, j = subdomain_idx_to_grid(subdomain_idx, nx_sub, ny_sub)
    
    # Calculate subdomain width and height
    dx = (xmax - xmin) / nx_sub
    dy = (ymax - ymin) / ny_sub
    
    # Calculate subdomain boundaries (non-overlapping)
    x_min = xmin + i * dx
    x_max = xmin + (i + 1) * dx
    y_min = ymin + j * dy
    y_max = ymin + (j + 1) * dy
    
    return (x_min, x_max, y_min, y_max)


def get_interfaces(nx_sub, ny_sub):
    """
    Identify all interfaces between adjacent subdomains.
    
    Args:
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        List of tuples (subdomain_i, subdomain_j, interface_type, position_idx)
        where:
        - subdomain_i, subdomain_j: indices of adjacent subdomains
        - interface_type: 'vertical', 'horizontal', 'periodic_vertical', or 'periodic_horizontal'
        - position_idx: which vertical/horizontal line (for position calculation)
    """
    interfaces = []
    
    # Vertical interfaces (constant x, between subdomains in x-direction)
    for i in range(nx_sub - 1):  # Between x-slices i and i+1
        for j in range(ny_sub):  # For each y-slice
            subdomain_left = i * ny_sub + j
            subdomain_right = (i + 1) * ny_sub + j
            interfaces.append((subdomain_left, subdomain_right, 'vertical', i + 1))
    
    # Horizontal interfaces (constant y, between subdomains in y-direction)
    for i in range(nx_sub):  # For each x-slice
        for j in range(ny_sub - 1):  # Between y-slices j and j+1
            subdomain_bottom = i * ny_sub + j
            subdomain_top = i * ny_sub + (j + 1)
            interfaces.append((subdomain_bottom, subdomain_top, 'horizontal', j + 1))
    
    # Periodic wrap-around interfaces (enforce periodic BC across domain boundaries)
    # Vertical wrap-around: right edge ↔ left edge (at x=xmax ↔ x=xmin)
    for j in range(ny_sub):  # For each y-slice
        subdomain_left = 0 * ny_sub + j              # Leftmost column (i=0)
        subdomain_right = (nx_sub - 1) * ny_sub + j  # Rightmost column (i=nx_sub-1)
        interfaces.append((subdomain_right, subdomain_left, 'periodic_vertical', nx_sub))
    
    # Horizontal wrap-around: top edge ↔ bottom edge (at y=ymax ↔ y=ymin)
    for i in range(nx_sub):  # For each x-slice
        subdomain_bottom = i * ny_sub + 0              # Bottom row (j=0)
        subdomain_top = i * ny_sub + (ny_sub - 1)      # Top row (j=ny_sub-1)
        interfaces.append((subdomain_top, subdomain_bottom, 'periodic_horizontal', ny_sub))
    
    return interfaces


def generate_interface_points(interface_info, xmin, xmax, ymin, ymax, 
                               tmin, tmax, n_points, device='cpu'):
    """
    Generate collocation points along an interface.
    
    Args:
        interface_info: Tuple (subdomain_i, subdomain_j, interface_type, position_idx)
        xmin, xmax: Global domain x-bounds
        ymin, ymax: Global domain y-bounds
        tmin, tmax: Time bounds
        n_points: Number of collocation points to generate
        device: PyTorch device
    
    Returns:
        List [x, y, t] of torch tensors with gradients enabled
    """
    subdomain_i, subdomain_j, interface_type, position_idx = interface_info
    
    # Generate points uniformly distributed along the interface and in time
    # Split n_points between spatial and temporal sampling
    n_spatial = max(int(np.sqrt(n_points)), 1)
    n_temporal = max(n_points // n_spatial, 1)
    
    if interface_type in ('vertical', 'periodic_vertical'):
        # Constant x interface
        from config import NUM_SUBDOMAINS_X
        dx = (xmax - xmin) / NUM_SUBDOMAINS_X
        
        if interface_type == 'periodic_vertical':
            # Periodic wrap-around: sample at x=xmax (which is equivalent to x=xmin due to periodic BC)
            x_interface = xmax
        else:
            # Interior vertical interface
            x_interface = xmin + position_idx * dx
        
        # Sample along y and t
        y_vals = torch.empty(n_spatial, 1, device=device, dtype=torch.float32).uniform_(ymin, ymax).requires_grad_()
        t_vals = torch.empty(n_temporal, 1, device=device, dtype=torch.float32).uniform_(tmin, tmax).requires_grad_()
        
        # Create meshgrid-like structure
        y_grid = y_vals.repeat(n_temporal, 1)
        t_grid = t_vals.repeat_interleave(n_spatial, dim=0)
        x_grid = torch.full_like(y_grid, x_interface).requires_grad_()
        
    else:  # 'horizontal' or 'periodic_horizontal'
        # Constant y interface
        from config import NUM_SUBDOMAINS_Y
        dy = (ymax - ymin) / NUM_SUBDOMAINS_Y
        
        if interface_type == 'periodic_horizontal':
            # Periodic wrap-around: sample at y=ymax (which is equivalent to y=ymin due to periodic BC)
            y_interface = ymax
        else:
            # Interior horizontal interface
            y_interface = ymin + position_idx * dy
        
        # Sample along x and t
        x_vals = torch.empty(n_spatial, 1, device=device, dtype=torch.float32).uniform_(xmin, xmax).requires_grad_()
        t_vals = torch.empty(n_temporal, 1, device=device, dtype=torch.float32).uniform_(tmin, tmax).requires_grad_()
        
        # Create meshgrid-like structure
        x_grid = x_vals.repeat(n_temporal, 1)
        t_grid = t_vals.repeat_interleave(n_spatial, dim=0)
        y_grid = torch.full_like(x_grid, y_interface).requires_grad_()
    
    # Ensure all have gradients enabled
    if not x_grid.requires_grad:
        x_grid = x_grid.requires_grad_()
    if not y_grid.requires_grad:
        y_grid = y_grid.requires_grad_()
    if not t_grid.requires_grad:
        t_grid = t_grid.requires_grad_()
    
    return [x_grid, y_grid, t_grid]


def generate_subdomain_collocation(subdomain_bounds, n_residual, n_ic, 
                                    tmin, tmax, startup_dt, device='cpu'):
    """
    Generate residual and IC collocation points within a subdomain.
    
    Args:
        subdomain_bounds: Tuple (x_min, x_max, y_min, y_max)
        n_residual: Number of residual collocation points
        n_ic: Number of initial condition points
        tmin, tmax: Time bounds
        startup_dt: Time offset for PDE enforcement
        device: PyTorch device
    
    Returns:
        Tuple (colloc_domain, colloc_ic) where each is a list [x, y, t]
    """
    x_min, x_max, y_min, y_max = subdomain_bounds
    
    # Generate residual/domain collocation points
    x_domain = torch.empty(n_residual, 1, device=device, dtype=torch.float32).uniform_(x_min, x_max).requires_grad_()
    y_domain = torch.empty(n_residual, 1, device=device, dtype=torch.float32).uniform_(y_min, y_max).requires_grad_()
    # Shift PDE enforcement to start at t = startup_dt (like original implementation)
    t_domain = torch.empty(n_residual, 1, device=device, dtype=torch.float32).uniform_(max(tmin, startup_dt), tmax).requires_grad_()
    colloc_domain = [x_domain, y_domain, t_domain]
    
    # Generate initial condition collocation points (at t=0)
    x_ic = torch.empty(n_ic, 1, device=device, dtype=torch.float32).uniform_(x_min, x_max).requires_grad_()
    y_ic = torch.empty(n_ic, 1, device=device, dtype=torch.float32).uniform_(y_min, y_max).requires_grad_()
    t_ic = torch.empty(n_ic, 1, device=device, dtype=torch.float32).fill_(tmin).requires_grad_()
    colloc_ic = [x_ic, y_ic, t_ic]
    
    return (colloc_domain, colloc_ic)


def point_in_subdomain(x, y, subdomain_bounds):
    """
    Check if point(s) belong to a subdomain.
    
    Args:
        x, y: Coordinates (can be scalars, arrays, or tensors)
        subdomain_bounds: Tuple (x_min, x_max, y_min, y_max)
    
    Returns:
        Boolean or boolean array indicating if points are in subdomain
    """
    x_min, x_max, y_min, y_max = subdomain_bounds
    
    # Handle both numpy arrays and torch tensors
    if isinstance(x, torch.Tensor):
        in_x = (x >= x_min) & (x <= x_max)
        in_y = (y >= y_min) & (y <= y_max)
    else:
        in_x = (x >= x_min) & (x <= x_max)
        in_y = (y >= y_min) & (y <= y_max)
    
    return in_x & in_y


def get_exterior_boundary_info(subdomain_idx, nx_sub, ny_sub, xmin, xmax, ymin, ymax):
    """
    Determine which boundaries of a subdomain are exterior boundaries.
    
    Args:
        subdomain_idx: Linear subdomain index
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
        xmin, xmax: Global domain x-bounds
        ymin, ymax: Global domain y-bounds
    
    Returns:
        Dict with keys 'left', 'right', 'bottom', 'top' indicating if boundary is exterior
        and corresponding coordinate values
    """
    i, j = subdomain_idx_to_grid(subdomain_idx, nx_sub, ny_sub)
    x_min, x_max, y_min, y_max = get_subdomain_bounds(subdomain_idx, xmin, xmax, ymin, ymax, nx_sub, ny_sub)
    
    boundary_info = {
        'left': (i == 0, x_min),           # Left edge of domain
        'right': (i == nx_sub - 1, x_max), # Right edge of domain
        'bottom': (j == 0, y_min),         # Bottom edge of domain
        'top': (j == ny_sub - 1, y_max)    # Top edge of domain
    }
    
    return boundary_info


# ==================== XPINN Setup and Initialization ====================

def setup_xpinn_devices(num_subdomains, device, use_multi_gpu=False):
    """
    Setup device assignment for XPINN subdomains.
    
    Args:
        num_subdomains: Total number of subdomains
        device: Default device
        use_multi_gpu: Whether to use multi-GPU setup
    
    Returns:
        Tuple (subdomain_devices, num_gpus)
    """
    if use_multi_gpu and torch.cuda.is_available():
        num_gpus = torch.cuda.device_count()
        print(f"Multi-GPU enabled: {num_gpus} GPUs available")
        devices = [f"cuda:{i}" for i in range(num_gpus)]
        subdomain_devices = [devices[i % len(devices)] for i in range(num_subdomains)]
    else:
        num_gpus = 1
        subdomain_devices = [device] * num_subdomains
    
    return subdomain_devices, num_gpus


def setup_xpinn_networks(num_subdomains, subdomain_devices, xmin, xmax, ymin, ymax, 
                         dimension, num_neurons, num_layers, harmonics, 
                         default_activation, nx_sub, ny_sub):
    """
    Initialize XPINN subdomain networks.
    
    Args:
        num_subdomains: Total number of subdomains
        subdomain_devices: List of device assignments per subdomain
        xmin, xmax, ymin, ymax: Global domain bounds
        dimension: Spatial dimension
        num_neurons: Default number of neurons per layer
        num_layers: Default number of hidden layers
        harmonics: Default number of Fourier harmonics
        default_activation: Default activation function type
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        List of initialized neural networks
    """
    from config import SUBDOMAIN_CONFIGS
    from core.model_architecture import PINN
    
    # Validate subdomain configs
    subdomain_configs = None
    if SUBDOMAIN_CONFIGS and len(SUBDOMAIN_CONFIGS) != num_subdomains:
        print(f"WARNING: SUBDOMAIN_CONFIGS has {len(SUBDOMAIN_CONFIGS)} entries but {num_subdomains} subdomains expected.")
        print(f"         Using global defaults for all subdomains.")
    elif SUBDOMAIN_CONFIGS:
        subdomain_configs = SUBDOMAIN_CONFIGS
    
    nets = []
    for i in range(num_subdomains):
        # Get subdomain-specific configuration or use defaults
        if subdomain_configs and i < len(subdomain_configs):
            config = subdomain_configs[i]
            sub_neurons = config.get('num_neurons', num_neurons)
            sub_layers = config.get('num_layers', num_layers)
            sub_harmonics = config.get('n_harmonics', harmonics)
            sub_activation = config.get('activation', default_activation)
        else:
            sub_neurons = num_neurons
            sub_layers = num_layers
            sub_harmonics = harmonics
            sub_activation = default_activation
        
        # Create network
        net = PINN(num_neurons=sub_neurons, num_layers=sub_layers, 
                  n_harmonics=sub_harmonics, activation_type=sub_activation)
        
        # Use GLOBAL domain for periodic embeddings
        net.set_domain(rmin=[xmin, ymin], rmax=[xmax, ymax], dimension=dimension)
        net = net.to(subdomain_devices[i])
        nets.append(net)
        
        # Print configuration
        subdomain_bounds = get_subdomain_bounds(i, xmin, xmax, ymin, ymax, nx_sub, ny_sub)
        print(f"  Subdomain {i}: bounds={subdomain_bounds}")
        print(f"    Architecture: neurons={sub_neurons}, layers={sub_layers}, harmonics={sub_harmonics}, activation={sub_activation}, device={subdomain_devices[i]}")
    
    return nets


def setup_xpinn_collocation(num_subdomains, subdomain_devices, xmin, xmax, ymin, ymax, 
                            tmin, tmax, n_r, n_0, startup_dt, nx_sub, ny_sub):
    """
    Generate collocation points for XPINN subdomains.
    
    Args:
        num_subdomains: Total number of subdomains
        subdomain_devices: Device assignment per subdomain
        xmin, xmax, ymin, ymax: Domain bounds
        tmin, tmax: Time bounds
        n_r: Total residual collocation points
        n_0: Total IC collocation points
        startup_dt: Time offset for PDE enforcement
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        Tuple (subdomain_collocs, subdomain_ic_collocs)
    """
    from core.data_generator import distribute_collocation_points
    
    # Distribute points
    n_r_per_subdomain = distribute_collocation_points(n_r, num_subdomains)
    n_0_per_subdomain = distribute_collocation_points(n_0, num_subdomains)
    
    subdomain_collocs = []
    subdomain_ic_collocs = []
    
    for i in range(num_subdomains):
        subdomain_bounds = get_subdomain_bounds(i, xmin, xmax, ymin, ymax, nx_sub, ny_sub)
        colloc_domain, colloc_ic = generate_subdomain_collocation(
            subdomain_bounds, n_r_per_subdomain[i], n_0_per_subdomain[i],
            tmin, tmax, startup_dt, device=subdomain_devices[i]
        )
        subdomain_collocs.append(colloc_domain)
        subdomain_ic_collocs.append(colloc_ic)
    
    return subdomain_collocs, subdomain_ic_collocs


def setup_xpinn_interfaces(subdomain_devices, xmin, xmax, ymin, ymax, tmin, tmax, 
                           n_interface, nx_sub, ny_sub):
    """
    Generate interface collocation points for XPINN.
    
    Args:
        subdomain_devices: Device assignment per subdomain
        xmin, xmax, ymin, ymax: Domain bounds
        tmin, tmax: Time bounds
        n_interface: Number of interface collocation points
        nx_sub: Number of subdomain splits in x-direction
        ny_sub: Number of subdomain splits in y-direction
    
    Returns:
        Tuple (interfaces, interface_collocs)
    """
    interfaces = get_interfaces(nx_sub, ny_sub)
    
    interface_collocs = {}
    for interface in interfaces:
        subdomain_i, subdomain_j, _, _ = interface
        interface_device = subdomain_devices[subdomain_i]
        interface_points = generate_interface_points(
            interface, xmin, xmax, ymin, ymax, tmin, tmax, n_interface, device=interface_device
        )
        interface_collocs[(subdomain_i, subdomain_j)] = interface_points
    
    return interfaces, interface_collocs


def cache_xpinn_initial_conditions(num_subdomains, subdomain_ic_collocs, ic_functions):
    """
    Pre-compute and cache initial condition values for all subdomains.
    
    Args:
        num_subdomains: Total number of subdomains
        subdomain_ic_collocs: IC collocation points per subdomain
        ic_functions: Dictionary of IC functions
    
    Returns:
        List of cached IC dictionaries per subdomain
    """
    print("Caching IC values for all subdomains...")
    cached_ic_values = []
    
    for i in range(num_subdomains):
        colloc_ic = subdomain_ic_collocs[i]
        ic_cache = {
            'rho': ic_functions['rho'](colloc_ic),
            'vx': ic_functions['vx'](colloc_ic),
            'vy': ic_functions['vy'](colloc_ic),
            'phi': ic_functions['phi'](colloc_ic)
        }
        cached_ic_values.append(ic_cache)
    
    print("IC values cached successfully!")
    return cached_ic_values
_register_module('methods.xpinn_decomposition', ['cache_xpinn_initial_conditions', 'generate_interface_points', 'generate_subdomain_collocation', 'get_exterior_boundary_info', 'get_interfaces', 'get_num_subdomains', 'get_subdomain_bounds', 'point_in_subdomain', 'setup_xpinn_collocation', 'setup_xpinn_devices', 'setup_xpinn_interfaces', 'setup_xpinn_networks', 'subdomain_idx_to_grid'])

# ==== Module: utilities.training_diagnostics (utilities/training_diagnostics.py) ====
import os
import numpy as np
import torch
import matplotlib.pyplot as plt


class TrainingDiagnostics:
    """Lightweight real-time diagnostics during training."""

    def __init__(self, save_dir='./diagnostics/'):
        self.save_dir = save_dir
        os.makedirs(save_dir, exist_ok=True)

        # Storage for tracking metrics over iterations
        self.history = {
            'iteration': [],
            'total_loss': [],
            'pde_loss': [],
            'ic_loss': [],
            'mean_rho': [],
            'max_rho': [],
            'mean_grad_rho': [],
            'max_grad_rho': [],
            'mean_residual': [],
            'max_residual': []
        }

    def _prepare_inputs(self, geomtime_col):
        """Normalize collocation inputs to the model's expected format."""
        if isinstance(geomtime_col, (list, tuple)):
            return geomtime_col
        # Single tensor [N, D] -> list of [N,1]
        return [geomtime_col[:, i:i+1] for i in range(geomtime_col.shape[1])]

    def log_iteration(self, iteration, model, loss_dict, geomtime_col):
        """Call this every N iterations during training."""
        self.history['iteration'].append(iteration)
        self.history['total_loss'].append(float(loss_dict.get('total', np.nan)))
        self.history['pde_loss'].append(float(loss_dict.get('pde', np.nan)))
        self.history['ic_loss'].append(float(loss_dict.get('ic', np.nan)))

        # Compute diagnostics from current model state
        with torch.no_grad():
            inputs = self._prepare_inputs(geomtime_col)
            pred = model(inputs)
            # Use first channel as density/log-density proxy
            rho = pred[:, 0].detach().cpu().numpy()

            # Density statistics
            self.history['mean_rho'].append(np.nanmean(rho))
            self.history['max_rho'].append(np.nanmax(rho))

            # Gradient proxies from predictions (fast approximate)
            self.history['mean_grad_rho'].append(float(np.nanstd(rho)))
            self.history['max_grad_rho'].append(float(np.nanmax(np.abs(np.diff(rho)))))

            # Residual statistics (optional, if provided as array-like)
            residual = loss_dict.get('residual', None)
            if residual is not None:
                res_np = np.asarray(residual)
                self.history['mean_residual'].append(float(np.nanmean(np.abs(res_np))))
                self.history['max_residual'].append(float(np.nanmax(np.abs(res_np))))

    def plot_diagnostics(self, iteration=None):
        """Generate all diagnostic plots as separate files. Call at the end of training."""
        if len(self.history['iteration']) == 0:
            print("No diagnostic data to plot.")
            return
        
        iters = self.history['iteration']
        suffix = f"_iter_{iteration}" if iteration is not None else "_final"

        # Plot 1: Loss evolution
        fig, ax = plt.subplots(figsize=(8, 6))
        ax.semilogy(iters, self.history['total_loss'], 'b-', linewidth=2, label='Total')
        ax.semilogy(iters, self.history['pde_loss'], 'r-', linewidth=2, label='PDE')
        ax.semilogy(iters, self.history['ic_loss'], 'g-', linewidth=2, label='IC')
        ax.set_xlabel('Iteration')
        ax.set_ylabel('Loss (log scale)')
        ax.set_title('Loss Components')
        ax.legend()
        ax.grid(True, alpha=0.3)
        plt.tight_layout()
        plt.savefig(f'{self.save_dir}/loss_components{suffix}.png', dpi=120, bbox_inches='tight')
        plt.close()

        # Plot 2: Loss ratio (PDE/IC)
        fig, ax = plt.subplots(figsize=(8, 6))
        ic_arr = np.array(self.history['ic_loss'])
        pde_arr = np.array(self.history['pde_loss'])
        ratio = pde_arr / (ic_arr + 1e-10)
        ax.plot(iters, ratio, 'purple', linewidth=2)
        ax.axhline(1.0, color='k', linestyle='--', label='Balanced')
        ax.set_xlabel('Iteration')
        ax.set_ylabel('PDE Loss / IC Loss')
        ax.set_title('Loss Balance (Should be ~1)')
        ax.legend()
        ax.grid(True, alpha=0.3)
        plt.tight_layout()
        plt.savefig(f'{self.save_dir}/loss_balance{suffix}.png', dpi=120, bbox_inches='tight')
        plt.close()

        # Plot 3: Density statistics
        fig, ax = plt.subplots(figsize=(8, 6))
        ax.plot(iters, self.history['mean_rho'], 'b-', linewidth=2, label='Mean ρ')
        ax.plot(iters, self.history['max_rho'], 'r-', linewidth=2, label='Max ρ')
        ax.set_xlabel('Iteration')
        ax.set_ylabel('Density')
        ax.set_title('Density Evolution')
        ax.legend()
        ax.grid(True, alpha=0.3)
        plt.tight_layout()
        plt.savefig(f'{self.save_dir}/density_evolution{suffix}.png', dpi=120, bbox_inches='tight')
        plt.close()

        # Plot 4: Max density growth rate
        if len(self.history['max_rho']) > 10:
            fig, ax = plt.subplots(figsize=(8, 6))
            growth_rate = np.diff(self.history['max_rho'])
            ax.plot(iters[1:], growth_rate, 'orange', linewidth=2)
            ax.axhline(0, color='k', linestyle='--')
            ax.set_xlabel('Iteration')
            ax.set_ylabel('Δ(Max ρ)')
            ax.set_title('Density Growth Rate (Should be positive)')
            ax.grid(True, alpha=0.3)
            plt.tight_layout()
            plt.savefig(f'{self.save_dir}/density_growth_rate{suffix}.png', dpi=120, bbox_inches='tight')
            plt.close()

        # Plot 5: Gradient magnitude
        fig, ax = plt.subplots(figsize=(8, 6))
        ax.semilogy(iters, self.history['mean_grad_rho'], 'b-', linewidth=2, label='Mean')
        ax.semilogy(iters, self.history['max_grad_rho'], 'r-', linewidth=2, label='Max')
        ax.set_xlabel('Iteration')
        ax.set_ylabel('Gradient Magnitude (log)')
        ax.set_title('Density Gradients')
        ax.legend()
        ax.grid(True, alpha=0.3)
        plt.tight_layout()
        plt.savefig(f'{self.save_dir}/density_gradients{suffix}.png', dpi=120, bbox_inches='tight')
        plt.close()

        # Plot 6: Residual statistics (if available)
        if len(self.history['mean_residual']) > 0:
            fig, ax = plt.subplots(figsize=(8, 6))
            ax.semilogy(iters, self.history['mean_residual'], 'b-', linewidth=2, label='Mean')
            ax.semilogy(iters, self.history['max_residual'], 'r-', linewidth=2, label='Max')
            ax.set_xlabel('Iteration')
            ax.set_ylabel('Residual Magnitude (log)')
            ax.set_title('PDE Residuals')
            ax.legend()
            ax.grid(True, alpha=0.3)
            plt.tight_layout()
            plt.savefig(f'{self.save_dir}/pde_residuals{suffix}.png', dpi=120, bbox_inches='tight')
            plt.close()
        
        print(f"Diagnostic plots saved to {self.save_dir}")
_register_module('utilities.training_diagnostics', ['TrainingDiagnostics'])

# ==== Module: training.physics (training/physics.py) ====
import numpy as np

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.autograd import Variable
from core.losses import ASTPN, pde_residue
from utilities.training_diagnostics import TrainingDiagnostics
from core.data_generator import diff
from core.model_architecture import PINN
from methods.causal_training import compute_causal_weights_static
from core.initial_conditions import (initialize_shared_velocity_fields, generate_power_spectrum_field, 
                                     generate_power_spectrum_field_vy, fun_rho_0, fun_vx_0, fun_vy_0, fun_vz_0)
from config import cs, const, G, rho_o, PERTURBATION_TYPE, KX, KY, BATCH_SIZE, NUM_BATCHES, RANDOM_SEED
from config import IC_WEIGHT, ENABLE_TRAINING_DIAGNOSTICS


# ==================== Physics Calculations and Loss Functions ====================

def closure(model, net, mse_cost_function, collocation_domain, collocation_IC, optimizer, rho_1, lam, jeans, v_1, data_terms=None):

    ############## Loss based on initial conditions ###############
    rho_0 = fun_rho_0(rho_1, lam, collocation_IC)
    vx_0  = fun_vx_0(lam, jeans, v_1, collocation_IC)

    if model.dimension == 2:
        vy_0  = fun_vy_0(lam, jeans, v_1, collocation_IC)

    elif model.dimension == 3:
        vy_0  = fun_vy_0(lam, jeans, v_1, collocation_IC)
        vz_0  = fun_vz_0(lam, jeans, v_1, collocation_IC)
    
    net_ic_out = net(collocation_IC)

    rho_ic_out = net_ic_out[:,0:1]
    vx_ic_out  = net_ic_out[:,1:2]

    if model.dimension == 2:
        vy_ic_out  = net_ic_out[:,2:3]
    elif model.dimension == 3:
        vy_ic_out  = net_ic_out[:,2:3]
        vz_ic_out  = net_ic_out[:,3:4]

    # For sinusoidal: enforce only explicit sinusoidal ICs; skip continuity seeding
    is_sin = str(PERTURBATION_TYPE).lower() == "sinusoidal"
    if is_sin:
        x_ic_for_ic = collocation_IC[0]
        if len(collocation_IC) >= 2:  # 2D case
            y_ic_for_ic = collocation_IC[1]
            rho_ic_target = rho_o + rho_1 * torch.cos(KX * x_ic_for_ic + KY * y_ic_for_ic)
        else:  # 1D case
            rho_ic_target = rho_o + rho_1 * torch.cos(2*np.pi*x_ic_for_ic/lam)
        mse_rho_ic = mse_cost_function(rho_ic_out, rho_ic_target)
    else:
        mse_rho_ic = 0.0 * torch.mean(rho_ic_out*0)

    mse_vx_ic  =  mse_cost_function(vx_ic_out, vx_0)

    if model.dimension == 2:
        mse_vy_ic  =  mse_cost_function(vy_ic_out, vy_0)

    elif model.dimension == 3:
        mse_vy_ic  =  mse_cost_function(vy_ic_out, vy_0)
        mse_vz_ic  =  mse_cost_function(vz_ic_out, vz_0)

    ############## Loss based on PDE ###################################
    
    # Apply startup time offset to PDE collocation time only (IC remains at t=0)
    if isinstance(collocation_domain, (list, tuple)):
        colloc_shifted = list(collocation_domain)
    else:
        # Single tensor format: split into [x, y, t]
        colloc_shifted = [collocation_domain[:, i:i+1] for i in range(collocation_domain.shape[1])]

    if model.dimension == 1:
        # time is at index 1
        # Note: Domain collocation points now start from STARTUP_DT (set in data_generator.py)
        rho_r,vx_r,phi_r = pde_residue(colloc_shifted, net, dimension = 1)

    elif model.dimension == 2:
        # time is at index 2
        # Note: Domain collocation points now start from STARTUP_DT (set in data_generator.py)
        rho_r,vx_r,vy_r,phi_r = pde_residue(colloc_shifted, net, dimension = 2)

    elif model.dimension == 3:
        # time is at index 3
        # Note: Domain collocation points now start from STARTUP_DT (set in data_generator.py)
        rho_r,vx_r,vy_r,vz_r,phi_r = pde_residue(colloc_shifted, net, dimension = 3)
    

    mse_rho  = torch.mean(rho_r ** 2)
    mse_velx = torch.mean(vx_r  ** 2)

    if model.dimension == 2:
        mse_vely = torch.mean(vy_r  ** 2)

    elif model.dimension == 3:
        mse_vely = torch.mean(vy_r  ** 2)
        mse_velz = torch.mean(vz_r  ** 2)
    
    mse_phi  = torch.mean(phi_r ** 2)

    ic_weight = IC_WEIGHT

    ################### Combining the loss functions ####################
    if model.dimension == 1:
        base = ic_weight * mse_vx_ic + mse_rho + mse_velx + mse_phi
        loss = base + (mse_rho_ic if isinstance(mse_rho_ic, torch.Tensor) else 0.0)

    elif model.dimension == 2:
        base = ic_weight * (mse_vx_ic + mse_vy_ic) + mse_rho + mse_velx + mse_vely + mse_phi
        loss = base + (mse_rho_ic if isinstance(mse_rho_ic, torch.Tensor) else 0.0)

    elif model.dimension == 3:
        base = ic_weight * (mse_vx_ic + mse_vy_ic + mse_vz_ic) + mse_rho + mse_velx + mse_vely + mse_velz + mse_phi
        loss = base + (mse_rho_ic if isinstance(mse_rho_ic, torch.Tensor) else 0.0)

    
        #loss = mse_rho_ic + mse_vx_ic + mse_vy_ic + mse_vz_ic + \
        #rhox_b + rhoy_b + rhoz_b + vx_xb + vx_yb + vx_zb +  vy_xb + vy_yb + vy_zb + vz_xb + vz_yb + vz_zb + \
        #phi_xb + phi_xx_b + phi_yb + phi_yy_b +  phi_zb + phi_zz_b + mse_rho + mse_velx +  mse_vely + mse_velz + mse_phi 

    optimizer.zero_grad()
    loss.backward(retain_graph=True)
    
    # Create loss breakdown dictionary
    loss_breakdown = {}
    
    # IC losses (grouped together)
    ic_loss = mse_vx_ic.item()
    if isinstance(mse_rho_ic, torch.Tensor) and mse_rho_ic.item() > 0:
        ic_loss += mse_rho_ic.item()
    
    if model.dimension == 2:
        ic_loss += mse_vy_ic.item()
    elif model.dimension == 3:
        ic_loss += mse_vy_ic.item()
        ic_loss += mse_vz_ic.item()
    
    loss_breakdown['IC'] = ic_loss
    
    # PDE losses (grouped together)
    pde_loss = mse_rho.item() + mse_velx.item()
    
    if model.dimension == 2:
        pde_loss += mse_vely.item()
    elif model.dimension == 3:
        pde_loss += mse_vely.item()
        pde_loss += mse_velz.item()
    
    pde_loss += mse_phi.item()
    loss_breakdown['PDE'] = pde_loss

    data_loss_tensor, data_breakdown = _evaluate_data_terms(net, mse_cost_function, data_terms if data_terms else [])
    if data_loss_tensor is not None:
        loss = loss + data_loss_tensor
        for label, value in data_breakdown.items():
            loss_breakdown[label] = value

    return loss, loss_breakdown

# Note: train() and train_xpinn() functions have been moved to training/trainer.py

def _random_batch_indices(total_count, batch_size, device):
    actual = int(min(batch_size, total_count))
    return torch.randperm(total_count, device=device)[:actual]


def _make_batch_tensors(tensors_list, indices):
    """Create batch tensors by indexing. No cloning for speed."""
    return [t[indices] for t in tensors_list]


def _sample_data_term(dataset, batch_size):
    if dataset is None or dataset.get('x') is None or dataset.get('t') is None:
        return None
    count = int(dataset.get('count', dataset['x'].shape[0]))
    if count <= 0:
        return None
    device = dataset['x'].device
    bs = batch_size if batch_size is not None else count
    bs = max(1, min(int(bs), count))
    indices = _random_batch_indices(count, bs, device)

    def _slice(key):
        tensor = dataset.get(key)
        if tensor is None:
            return None
        return tensor[indices]

    return {
        'x': _slice('x'),
        'y': _slice('y'),
        'z': _slice('z'),
        't': _slice('t'),
        'rho': _slice('rho'),
        'vx': _slice('vx'),
        'vy': _slice('vy'),
        'phi': _slice('phi'),
    }


def _compute_data_loss_unweighted(net, batch, mse_cost_function):
    if batch is None or batch['x'] is None or batch['t'] is None:
        return None

    inputs = [batch['x']]
    if batch.get('y') is not None:
        inputs.append(batch['y'])
    if batch.get('z') is not None:
        inputs.append(batch['z'])
    inputs.append(batch['t'])

    outputs = net(inputs)
    num_outputs = outputs.shape[1]

    component_specs = [
        ('rho', 0),
        ('vx', 1),
        ('vy', 2),
        ('phi', 3),
    ]

    losses = []
    for key, idx in component_specs:
        target = batch.get(key)
        if target is None or idx >= num_outputs:
            continue
        pred = outputs[:, idx:idx+1]
        losses.append(mse_cost_function(pred, target))

    if not losses:
        return None
    return sum(losses) / len(losses)


def _evaluate_data_terms(net, mse_cost_function, data_terms):
    if not data_terms:
        return None, {}

    total_loss = None
    breakdown = {}

    for term in data_terms:
        dataset = term.get('dataset')
        weight = float(term.get('weight', 0.0) or 0.0)
        if dataset is None or weight <= 0:
            continue
        batch = _sample_data_term(dataset, term.get('batch_size'))
        data_loss = _compute_data_loss_unweighted(net, batch, mse_cost_function)
        if data_loss is None:
            continue
        weighted_loss = weight * data_loss
        total_loss = weighted_loss if total_loss is None else total_loss + weighted_loss
        label = term.get('label', 'DATA')
        breakdown[label] = breakdown.get(label, 0.0) + float(weighted_loss.detach().cpu())

    return total_loss, breakdown


def closure_batched(model, net, mse_cost_function, collocation_domain, collocation_IC, optimizer,
                    rho_1, lam, jeans, v_1, batch_size, num_batches, causal_gamma=0.0, causal_mode="none", residual_tracker=None, update_tracker=True, iteration=0, use_fft_poisson=None, data_terms=None, collocation_poisson_ic=None):
    """
    Batched closure function for training with optional causal weighting.
    
    This function computes losses over mini-batches and optionally applies causal weights.
    """
    # Aggregate losses across mini-batches
    total_loss = 0.0
    num_effective_batches = 0

    # Determine counts and devices
    # Handle both formats: list of tensors [x, y, t] or single tensor [N, 3]
    if isinstance(collocation_domain, (list, tuple)):
        dom_n = collocation_domain[0].size(0)
        device = collocation_domain[0].device
    else:
        dom_n = collocation_domain.size(0)
        device = collocation_domain.device
    
    ic_n = collocation_IC[0].size(0)

    last_data_breakdown = {}

    for _ in range(int(max(1, num_batches))):
        dom_idx = _random_batch_indices(dom_n, batch_size, device)
        ic_idx = _random_batch_indices(ic_n, batch_size, device)

        # Handle both formats for collocation_domain
        if isinstance(collocation_domain, (list, tuple)):
            batch_dom = _make_batch_tensors(collocation_domain, dom_idx)
        else:
            # Single tensor format: split into [x, y, t]
            batch_dom = [collocation_domain[dom_idx, i:i+1] for i in range(collocation_domain.shape[1])]
        
        batch_ic = _make_batch_tensors(collocation_IC, ic_idx)

        # IC loss terms
        rho_0 = fun_rho_0(rho_1, lam, batch_ic)
        vx_0  = fun_vx_0(lam, jeans, v_1, batch_ic)

        net_ic_out = net(batch_ic)
        rho_ic_out = net_ic_out[:,0:1]
        vx_ic_out  = net_ic_out[:,1:2]

        if model.dimension == 2:
            vy_0 = fun_vy_0(lam, jeans, v_1, batch_ic)
            vy_ic_out = net_ic_out[:,2:3]
        elif model.dimension == 3:
            vy_0 = fun_vy_0(lam, jeans, v_1, batch_ic)
            vz_0 = fun_vz_0(lam, jeans, v_1, batch_ic)
            vy_ic_out = net_ic_out[:,2:3]
            vz_ic_out = net_ic_out[:,3:4]

        is_sin = str(PERTURBATION_TYPE).lower() == "sinusoidal"
        if is_sin:
            x_ic_for_ic = batch_ic[0]
            if len(batch_ic) >= 2:
                y_ic_for_ic = batch_ic[1]
                rho_ic_target = rho_o + rho_1 * torch.cos(KX * x_ic_for_ic + KY * y_ic_for_ic)
            else:
                rho_ic_target = rho_o + rho_1 * torch.cos(2*np.pi*x_ic_for_ic/lam)
            mse_rho_ic = mse_cost_function(rho_ic_out, rho_ic_target)
        else:
            mse_rho_ic = 0.0 * torch.mean(rho_ic_out*0)

        mse_vx_ic  = mse_cost_function(vx_ic_out, vx_0)
        if model.dimension == 2:
            mse_vy_ic = mse_cost_function(vy_ic_out, vy_0)
        elif model.dimension == 3:
            mse_vy_ic = mse_cost_function(vy_ic_out, vy_0)
            mse_vz_ic = mse_cost_function(vz_ic_out, vz_0)

        # PDE residuals on batched domain with startup shift
        if isinstance(batch_dom, (list, tuple)):
            colloc_shifted = list(batch_dom)
        else:
            # Single tensor format: split into [x, y, t]
            colloc_shifted = [batch_dom[:, i:i+1] for i in range(batch_dom.shape[1])]
        if model.dimension == 1:
            # Note: Domain collocation points already start from STARTUP_DT, no need to shift further
            rho_r, vx_r, phi_r = pde_residue(colloc_shifted, net, dimension=1)
        elif model.dimension == 2:
            # Note: Domain collocation points already start from STARTUP_DT, no need to shift further
            rho_r, vx_r, vy_r, phi_r = pde_residue(colloc_shifted, net, dimension=2)
        else:
            # Note: Domain collocation points already start from STARTUP_DT, no need to shift further
            rho_r, vx_r, vy_r, vz_r, phi_r = pde_residue(colloc_shifted, net, dimension=3)

        # Extract time values from batch_dom
        if model.dimension == 1:
            t_dom = batch_dom[1]
        elif model.dimension == 2:
            t_dom = batch_dom[2]
        elif model.dimension == 3:
            t_dom = batch_dom[3]

        # Compute causal weights for PDE residuals based on mode
        causal_weights = None
        if causal_mode == "static" and causal_gamma > 0.0:
            # Static exponential weighting
            causal_weights = compute_causal_weights_static(t_dom, causal_gamma)
        elif causal_mode == "adaptive" and residual_tracker is not None:
            # Adaptive residual-based weighting
            causal_weights = residual_tracker.get_adaptive_weights(t_dom)
        
        # Apply weights to PDE residuals
        if causal_weights is not None:
            mse_rho  = torch.mean(causal_weights * (rho_r ** 2))
            mse_velx = torch.mean(causal_weights * (vx_r ** 2))
            if model.dimension == 2:
                mse_vely = torch.mean(causal_weights * (vy_r ** 2))
            elif model.dimension == 3:
                mse_vely = torch.mean(causal_weights * (vy_r ** 2))
                mse_velz = torch.mean(causal_weights * (vz_r ** 2))
            mse_phi  = torch.mean(causal_weights * (phi_r ** 2))
        else:
            # Standard uniform weighting
            mse_rho  = torch.mean(rho_r ** 2)
            mse_velx = torch.mean(vx_r  ** 2)
            if model.dimension == 2:
                mse_vely = torch.mean(vy_r  ** 2)
            elif model.dimension == 3:
                mse_vely = torch.mean(vy_r  ** 2)
                mse_velz = torch.mean(vz_r  ** 2)
            mse_phi  = torch.mean(phi_r ** 2)

        if model.dimension == 1:
            base = mse_vx_ic + mse_rho + mse_velx + mse_phi
            loss = base + (mse_rho_ic if isinstance(mse_rho_ic, torch.Tensor) else 0.0)
        elif model.dimension == 2:
            base = mse_vx_ic + mse_vy_ic + mse_rho + mse_velx + mse_vely + mse_phi
            loss = base + (mse_rho_ic if isinstance(mse_rho_ic, torch.Tensor) else 0.0)
        else:
            base = mse_vx_ic + mse_vy_ic + mse_vz_ic + mse_rho + mse_velx + mse_vely + mse_velz + mse_phi
            loss = base + (mse_rho_ic if isinstance(mse_rho_ic, torch.Tensor) else 0.0)

        # Update residual tracker AFTER computing loss (only during Adam)
        # This ensures the tracker uses only past history for weight computation
        if causal_mode == "adaptive" and residual_tracker is not None and update_tracker:
            with torch.no_grad():
                if model.dimension == 1:
                    residual_tracker.update_residuals(t_dom, [rho_r, vx_r, phi_r])
                elif model.dimension == 2:
                    residual_tracker.update_residuals(t_dom, [rho_r, vx_r, vy_r, phi_r])
                else:
                    residual_tracker.update_residuals(t_dom, [rho_r, vx_r, vy_r, vz_r, phi_r])

        if data_terms:
            data_loss_batch, batch_breakdown = _evaluate_data_terms(net, mse_cost_function, data_terms)
            if data_loss_batch is not None:
                loss = loss + data_loss_batch
                last_data_breakdown = batch_breakdown

        total_loss = total_loss + loss
        num_effective_batches += 1
    
    # Add Poisson IC loss (Option 3: Pure ML approach for initial phi)
    # This enforces Poisson equation at t=0 with extra collocation points
    mse_poisson_ic = 0.0
    mse_phi_mean = 0.0
    if collocation_poisson_ic is not None:
        from core.losses import poisson_residue_only
        from config import POISSON_IC_WEIGHT, PHI_MEAN_CONSTRAINT_WEIGHT
        
        # Only compute and add Poisson IC loss if weight is non-zero
        if POISSON_IC_WEIGHT > 0:
            # Enforce Poisson equation: ∇²φ = const*(ρ-ρ₀)
            phi_r_ic = poisson_residue_only(collocation_poisson_ic, net, dimension=model.dimension)
            mse_poisson_ic = torch.mean(phi_r_ic ** 2)
            total_loss = total_loss + POISSON_IC_WEIGHT * mse_poisson_ic
        
        # Only compute and add phi mean constraint if weight is non-zero
        if PHI_MEAN_CONSTRAINT_WEIGHT > 0:
            # Enforce mean(φ) = 0 at t=0 to fix gauge freedom (Option A)
            # This removes the arbitrary constant offset in φ
            net_output_ic = net(collocation_poisson_ic)
            phi_ic = net_output_ic[:, -1]  # Last output is phi
            mean_phi = torch.mean(phi_ic)
            mse_phi_mean = mean_phi ** 2
            total_loss = total_loss + PHI_MEAN_CONSTRAINT_WEIGHT * mse_phi_mean

    optimizer.zero_grad()
    avg_loss = total_loss / max(1, num_effective_batches)
    avg_loss.backward(retain_graph=True)
    
    # Aggressive memory cleanup after backward pass
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    
    # Create loss breakdown dictionary (averaged across batches)
    loss_breakdown = {}
    
    # For batched version, we need to compute breakdown from the last batch
    # This is an approximation since we can't easily track individual terms across batches
    # IC losses (grouped together)
    ic_loss = mse_vx_ic.item()
    if isinstance(mse_rho_ic, torch.Tensor) and mse_rho_ic.item() > 0:
        ic_loss += mse_rho_ic.item()
    
    if model.dimension == 2:
        ic_loss += mse_vy_ic.item()
    elif model.dimension == 3:
        ic_loss += mse_vy_ic.item()
        ic_loss += mse_vz_ic.item()
    
    loss_breakdown['IC'] = ic_loss
    
    # PDE losses (grouped together)
    pde_loss = mse_rho.item() + mse_velx.item()
    
    if model.dimension == 2:
        pde_loss += mse_vely.item()
    elif model.dimension == 3:
        pde_loss += mse_vely.item()
        pde_loss += mse_velz.item()
    
    pde_loss += mse_phi.item()
    loss_breakdown['PDE'] = pde_loss
    
    # Add Poisson IC loss to breakdown if it was computed
    if isinstance(mse_poisson_ic, torch.Tensor):
        loss_breakdown['Poisson_IC'] = mse_poisson_ic.item()
    if isinstance(mse_phi_mean, torch.Tensor):
        loss_breakdown['Phi_Mean'] = mse_phi_mean.item()
    
    for label, value in last_data_breakdown.items():
        loss_breakdown[label] = value

    return avg_loss, loss_breakdown


# ==================== XPINN Physics Calculations ====================

def closure_xpinn(xpinn_loss_model, nets, subdomain_collocs, interface_collocs,
                   subdomain_ic_collocs, ic_functions, interfaces, exterior_boundaries,
                   optimizer, subdomain_devices=None, cached_ic_values=None):
    """
    Closure function for XPINN training with multiple networks.
    
    Args:
        xpinn_loss_model: XPINN_Loss instance
        nets: List of neural networks
        subdomain_collocs: List of subdomain collocation points
        interface_collocs: Dict of interface collocation points
        subdomain_ic_collocs: List of IC collocation points per subdomain
        ic_functions: Initial condition functions
        interfaces: List of interface tuples
        exterior_boundaries: Dict of exterior boundary info
        optimizer: Optimizer instance
        subdomain_devices: List of devices per subdomain
        cached_ic_values: Precomputed IC values
    
    Returns:
        Total loss (scalar tensor), loss_dict
    """
    optimizer.zero_grad()
    
    # Compute total XPINN loss (passing cached IC if available)
    total_loss, loss_dict = xpinn_loss_model.compute_total_loss(
        nets, subdomain_collocs, interface_collocs,
        subdomain_ic_collocs, ic_functions, interfaces,
        exterior_boundaries, cached_ic_values
    )
    
    # Backward pass
    total_loss.backward(retain_graph=True)
    
    return total_loss, loss_dict


def closure_xpinn_batched(xpinn_loss_model, nets, subdomain_collocs, interface_collocs,
                           subdomain_ic_collocs, ic_functions, interfaces, exterior_boundaries,
                           optimizer, batch_size, num_batches, subdomain_devices=None, cached_ic_values=None):
    """
    Batched closure function for XPINN training with multiple networks.
    Processes collocation points in mini-batches with gradient accumulation.
    
    Args:
        xpinn_loss_model: XPINN_Loss instance
        nets: List of neural networks
        subdomain_collocs: List of subdomain collocation points
        interface_collocs: Dict of interface collocation points
        subdomain_ic_collocs: List of IC collocation points per subdomain
        ic_functions: Initial condition functions
        interfaces: List of interface tuples
        exterior_boundaries: Dict of exterior boundary info
        optimizer: Optimizer instance
        batch_size: Maximum points per mini-batch
        num_batches: Number of mini-batches to aggregate
        subdomain_devices: List of devices per subdomain
        cached_ic_values: Precomputed IC values
    
    Returns:
        Total loss (scalar tensor), loss_dict
    """
    if subdomain_devices is None:
        subdomain_devices = [subdomain_collocs[0][0].device] * len(nets)
    if cached_ic_values is None:
        cached_ic_values = [None] * len(nets)
    optimizer.zero_grad()
    
    # Aggregate losses across mini-batches
    total_loss = 0.0
    num_effective_batches = 0
    
    # Get device from first subdomain's collocation points
    device = subdomain_collocs[0][0].device if len(subdomain_collocs) > 0 else 'cuda'
    
    for batch_idx in range(int(max(1, num_batches))):
        # Create batched subdomain collocation points (on correct devices)
        batched_subdomain_collocs = []
        for i, subdomain_colloc in enumerate(subdomain_collocs):
            dom_n = subdomain_colloc[0].size(0)
            sub_device = subdomain_devices[i]
            dom_idx = _random_batch_indices(dom_n, batch_size, sub_device)
            batch_dom = _make_batch_tensors(subdomain_colloc, dom_idx)
            batched_subdomain_collocs.append(batch_dom)
        
        # Create batched subdomain IC points and batched cached IC values
        batched_subdomain_ic_collocs = []
        batched_cached_ic = []
        for i, subdomain_ic_colloc in enumerate(subdomain_ic_collocs):
            ic_n = subdomain_ic_colloc[0].size(0)
            sub_device = subdomain_devices[i]
            ic_idx = _random_batch_indices(ic_n, batch_size, sub_device)
            batch_ic = _make_batch_tensors(subdomain_ic_colloc, ic_idx)
            batched_subdomain_ic_collocs.append(batch_ic)
            
            # Batch cached IC values if available
            if cached_ic_values[i] is not None:
                batched_ic_cache = {
                    key: val[ic_idx] for key, val in cached_ic_values[i].items()
                }
                batched_cached_ic.append(batched_ic_cache)
            else:
                batched_cached_ic.append(None)
        
        # Create batched interface collocation points (use device of first subdomain in pair)
        batched_interface_collocs = {}
        for interface_key, interface_colloc in interface_collocs.items():
            if_n = interface_colloc[0].size(0)
            # Use device of first subdomain in the interface pair
            sub_device = subdomain_devices[interface_key[0]]
            if_idx = _random_batch_indices(if_n, batch_size, sub_device)
            
            # Move interface collocation points to the correct device before indexing
            interface_colloc_on_device = [t.to(sub_device) for t in interface_colloc]
            batch_if = _make_batch_tensors(interface_colloc_on_device, if_idx)
            batched_interface_collocs[interface_key] = batch_if
        
        # Compute loss for this mini-batch (with cached IC if available)
        batch_loss, batch_loss_dict = xpinn_loss_model.compute_total_loss(
            nets, batched_subdomain_collocs, batched_interface_collocs,
            batched_subdomain_ic_collocs, ic_functions, interfaces,
            exterior_boundaries, batched_cached_ic
        )
        
        # Accumulate loss
        total_loss += batch_loss
        num_effective_batches += 1
    
    # Average loss across batches
    if num_effective_batches > 0:
        total_loss = total_loss / num_effective_batches
    
    # Backward pass
    total_loss.backward(retain_graph=True)
    
    # For batched XPINN, we need to compute breakdown from the last batch
    # This is an approximation since we can't easily track individual terms across batches
    # Note: batch_loss_dict is already computed from the last batch iteration above
    
    return total_loss, batch_loss_dict
_register_module('training.physics', ['_compute_data_loss_unweighted', '_evaluate_data_terms', '_make_batch_tensors', '_random_batch_indices', '_sample_data_term', 'closure', 'closure_batched', 'closure_xpinn', 'closure_xpinn_batched'])

# ==== Module: training.trainer (training/trainer.py) ====
"""
Training loop management for PINN and XPINN.

This module handles the optimization loops (Adam and L-BFGS) for both
single PINN and XPINN decomposition training.
"""
import numpy as np
import torch
from utilities.training_diagnostics import TrainingDiagnostics
from config import BATCH_SIZE, NUM_BATCHES, ENABLE_TRAINING_DIAGNOSTICS
from training.physics import closure_batched


def train(model, net, collocation_domain, collocation_IC, optimizer, optimizerL, iteration_adam, iterationL, mse_cost_function, closure, rho_1, lam, jeans, v_1, device, causal_gamma=0.0, causal_mode="none", residual_tracker=None, window_idx=None, data_terms=None, collocation_poisson_ic=None):
    """
    Standard training loop for single PINN.
    
    Manages Adam and L-BFGS optimization phases with cosine scheduling for
    continuity weight and startup_dt parameters.
    
    Args:
        model: Collocation model
        net: Neural network
        collocation_domain: Domain collocation points
        collocation_IC: Initial condition points
        optimizer: Adam optimizer
        optimizerL: L-BFGS optimizer
        iteration_adam: Number of Adam iterations
        iterationL: Number of L-BFGS iterations
        mse_cost_function: MSE loss function
        closure: Closure function (unused, kept for compatibility)
        rho_1: Perturbation amplitude
        lam: Wavelength
        jeans: Jeans length
        v_1: Velocity amplitude
        device: PyTorch device
        causal_gamma: Causal weighting parameter
        causal_mode: Causal training mode
        residual_tracker: Residual tracker for adaptive causal weighting
        window_idx: Current curriculum window index
        data_terms: Optional list of additional supervised datasets with weights
    """
    bs = int(BATCH_SIZE)
    nb = int(NUM_BATCHES)

    diagnostics = TrainingDiagnostics(save_dir='./diagnostics/') if ENABLE_TRAINING_DIAGNOSTICS else None

    for i in range(iteration_adam):
        optimizer.zero_grad()

        loss, loss_breakdown = optimizer.step(lambda: closure_batched(model, net, mse_cost_function, collocation_domain, collocation_IC, optimizer, rho_1, lam, jeans, v_1, bs, nb, causal_gamma, causal_mode, residual_tracker, update_tracker=True, iteration=i, use_fft_poisson=True, data_terms=data_terms, collocation_poisson_ic=collocation_poisson_ic))

        with torch.autograd.no_grad():
            # Diagnostics logging every 50 iterations
            if i % 50 == 0 and diagnostics is not None:
                try:
                    diagnostics.log_iteration(
                        iteration=i,
                        model=net,
                        loss_dict={
                            'total': loss.item(),
                            'pde': float(loss_breakdown.get('PDE', 0.0)),
                            'ic': float(loss_breakdown.get('IC', 0.0))
                        },
                        geomtime_col=collocation_domain
                    )
                except Exception as _diag_err:
                    # Keep training robust if diagnostics fail
                    print(f"[WARN] Diagnostics logging failed at {i}: {_diag_err}")

            if i % 100 == 0:
                print(f"Training Loss at {i} for Adam (batched) in {model.dimension}D system = {loss.item():.2e}", flush=True)
                # Print loss breakdown
                breakdown_str = " | ".join([f"{k}: {v:.2e}" for k, v in loss_breakdown.items() if v > 0])
                if breakdown_str:
                    print(f"  Loss breakdown: {breakdown_str}", flush=True)

    for i in range(iterationL):
        optimizer.zero_grad()
        global_step = iteration_adam + i

        # L-BFGS expects a closure that returns only scalar loss
        # Store loss_breakdown in a list so we can access it after the step
        loss_breakdown_holder = [None]
        
        def lbfgs_closure():
            loss, loss_breakdown = closure_batched(model, net, mse_cost_function, collocation_domain, collocation_IC, optimizerL, rho_1, lam, jeans, v_1, bs, nb, causal_gamma, causal_mode, residual_tracker, update_tracker=False, iteration=global_step, use_fft_poisson=False, data_terms=data_terms, collocation_poisson_ic=collocation_poisson_ic)
            loss_breakdown_holder[0] = loss_breakdown
            return loss
        
        loss = optimizerL.step(lbfgs_closure)
        loss_breakdown = loss_breakdown_holder[0]

        with torch.autograd.no_grad():
            # Diagnostics logging every 50 iterations in LBFGS too
            if i % 50 == 0 and loss_breakdown is not None and diagnostics is not None:
                try:
                    diagnostics.log_iteration(
                        iteration=iteration_adam + i,
                        model=net,
                        loss_dict={
                            'total': loss.item() if hasattr(loss, 'item') else float(loss),
                            'pde': float(loss_breakdown.get('PDE', 0.0)),
                            'ic': float(loss_breakdown.get('IC', 0.0))
                        },
                        geomtime_col=collocation_domain
                    )
                except Exception as _diag_err:
                    print(f"[WARN] Diagnostics logging (LBFGS) failed at {i}: {_diag_err}")
            if i % 50 == 0:
                print(f"Training Loss at {i} for LBGFS (batched) in {model.dimension}D system = {loss.item():.2e}", flush=True)
                # Print loss breakdown
                breakdown_str = " | ".join([f"{k}: {v:.2e}" for k, v in loss_breakdown.items() if v > 0])
                if breakdown_str:
                    print(f"  Loss breakdown: {breakdown_str}", flush=True)
    
    # Generate diagnostic plots at the end of training
    if diagnostics is not None:
        try:
            final_iteration = iteration_adam + iterationL - 1
            diagnostics.plot_diagnostics(final_iteration)
        except Exception as _diag_err:
            print(f"[WARN] Final diagnostics plotting failed: {_diag_err}")


def train_xpinn(nets, subdomain_collocs, interface_collocs, subdomain_ic_collocs,
                ic_functions, interfaces, exterior_boundaries, xpinn_loss_model,
                optimizer, optimizerL, iteration_adam, iterationL, device,
                subdomain_devices=None, cached_ic_values=None):
    """
    Training loop for XPINN with multiple networks.
    
    Manages Adam and L-BFGS optimization for domain decomposition, with support
    for multi-GPU training and per-subdomain optimization.
    
    Args:
        nets: List of neural networks (one per subdomain)
        subdomain_collocs: List of subdomain collocation points
        interface_collocs: Dict of interface collocation points
        subdomain_ic_collocs: List of IC collocation points per subdomain
        ic_functions: Initial condition functions dictionary
        interfaces: List of interface tuples
        exterior_boundaries: Dict of exterior boundary information
        xpinn_loss_model: XPINN_Loss instance
        optimizer: Adam optimizer
        optimizerL: L-BFGS optimizer
        iteration_adam: Number of Adam iterations
        iterationL: Number of L-BFGS iterations
        device: PyTorch device
        subdomain_devices: List of devices per subdomain (for multi-GPU)
        cached_ic_values: Precomputed IC values (list of dicts per subdomain)
    
    Returns:
        None (trains networks in-place)
    """
    from training.physics import closure_xpinn, closure_xpinn_batched, _random_batch_indices, _make_batch_tensors
    
    # Set defaults
    if subdomain_devices is None:
        subdomain_devices = [device] * len(nets)
    if cached_ic_values is None:
        cached_ic_values = [None] * len(nets)
    from config import XPINN_ALTERNATING_TRAINING, USE_XPINN_BATCHING
    
    # Determine if we need per-subdomain optimizers (multi-GPU case)
    use_per_subdomain_adam = (optimizer is None)
    
    if use_per_subdomain_adam:
        # Multi-GPU: create separate Adam optimizer for each subdomain
        print("Creating per-subdomain Adam optimizers for multi-GPU training...")
        adam_optimizers = [torch.optim.Adam(net.parameters(), lr=0.001) for net in nets]
    else:
        # Single-GPU: use unified optimizer
        adam_optimizers = None
        
        # Choose closure function based on batching setting
        if USE_XPINN_BATCHING:
            bs_global = int(BATCH_SIZE)
            nb = int(NUM_BATCHES)
            num_sub = len(nets)
            bs = max(1, bs_global // max(1, num_sub))  # per-subdomain batch size
            
            def make_closure(opt):
                return lambda: closure_xpinn_batched(
                    xpinn_loss_model, nets, subdomain_collocs, interface_collocs,
                    subdomain_ic_collocs, ic_functions, interfaces, exterior_boundaries,
                    opt, bs, nb, subdomain_devices, cached_ic_values
                )
        else:
            def make_closure(opt):
                return lambda: closure_xpinn(
                    xpinn_loss_model, nets, subdomain_collocs, interface_collocs,
                    subdomain_ic_collocs, ic_functions, interfaces, exterior_boundaries,
                    opt, subdomain_devices, cached_ic_values
                )
    
    # Adam training
    xpinn_diagnostics = TrainingDiagnostics(save_dir='./diagnostics/') if ENABLE_TRAINING_DIAGNOSTICS else None
    for i in range(iteration_adam):
        if use_per_subdomain_adam:
            # Per-subdomain Adam training (multi-GPU)
            # Process each subdomain completely independently to avoid graph sharing issues
            subdomain_losses = []
            
            # Track component losses across all subdomains
            total_pde_loss = 0.0
            total_ic_loss = 0.0
            total_interface_sol_loss = 0.0
            total_interface_res_loss = 0.0
            
            for sub_idx in range(len(nets)):
                try:
                    adam_optimizers[sub_idx].zero_grad()
                    
                    # Compute PDE and IC loss for this subdomain
                    # Create fresh copies of collocation points to avoid graph reuse across iterations
                    colloc_orig = subdomain_collocs[sub_idx]
                    colloc_ic_orig = subdomain_ic_collocs[sub_idx]
                    
                    colloc = [t.clone().detach().requires_grad_(True) for t in colloc_orig]
                    colloc_ic = [t.clone().detach().requires_grad_(False) for t in colloc_ic_orig]
                    
                    # Detach cached IC values to avoid graph reuse across iterations
                    cached_ic = None
                    if cached_ic_values and cached_ic_values[sub_idx] is not None:
                        cached_ic = {
                            key: val.detach() for key, val in cached_ic_values[sub_idx].items()
                        }
                    
                    pde_loss = xpinn_loss_model.compute_pde_loss(colloc, nets[sub_idx])
                    ic_loss = xpinn_loss_model.compute_ic_loss(colloc_ic, nets[sub_idx], ic_functions, cached_ic)
                    
                    total_loss = pde_loss + ic_loss
                    
                    # Track component losses
                    total_pde_loss += pde_loss.item()
                    total_ic_loss += ic_loss.item()
                    
                    # Accumulate all interface losses for this subdomain
                    interface_sol_loss_sum = 0.0
                    interface_res_loss_sum = 0.0
                    for interface in interfaces:
                        subdomain_i, subdomain_j, _, _ = interface
                        interface_key = (subdomain_i, subdomain_j)
                        
                        # Only compute interface losses where this subdomain participates
                        if sub_idx == subdomain_i or sub_idx == subdomain_j:
                            if interface_key in interface_collocs:
                                # Create fresh copies of interface collocation points to avoid graph sharing
                                colloc_interface = interface_collocs[interface_key]
                                colloc_interface_fresh = [t.clone().detach().requires_grad_(False) for t in colloc_interface]
                                
                                net1 = nets[subdomain_i]
                                net2 = nets[subdomain_j]
                                
                                # Backprop only to current subdomain's network
                                if sub_idx == subdomain_i:
                                    sol_loss = xpinn_loss_model.compute_interface_solution_loss(
                                        colloc_interface_fresh, net1, net2, grad_to='net1')
                                    res_loss = xpinn_loss_model.compute_interface_residual_loss(
                                        colloc_interface_fresh, net1, net2, grad_to='net1')
                                else:  # sub_idx == subdomain_j
                                    sol_loss = xpinn_loss_model.compute_interface_solution_loss(
                                        colloc_interface_fresh, net1, net2, grad_to='net2')
                                    res_loss = xpinn_loss_model.compute_interface_residual_loss(
                                        colloc_interface_fresh, net1, net2, grad_to='net2')
                                
                                interface_sol_loss_sum += sol_loss.item()
                                interface_res_loss_sum += res_loss.item()
                                
                                total_loss = total_loss + sol_loss + res_loss
                    
                    # Track interface losses
                    total_interface_sol_loss += interface_sol_loss_sum
                    total_interface_res_loss += interface_res_loss_sum
                    
                    # Single backward pass for this subdomain
                    total_loss.backward()
                    adam_optimizers[sub_idx].step()
                    subdomain_losses.append(total_loss.item())
                    
                except Exception as e:
                    print(f"Error in subdomain {sub_idx}: {e}")
                    raise
            
            # Diagnostics for XPINN (aggregate) every 50 iterations
            if i % 50 == 0 and len(nets) > 0 and len(subdomain_collocs) > 0 and xpinn_diagnostics is not None:
                try:
                    xpinn_diagnostics.log_iteration(
                        iteration=i,
                        model=nets[0],
                        loss_dict={
                            'total': float(np.mean(subdomain_losses)) if subdomain_losses else np.nan,
                            'pde': float(total_pde_loss / max(1, len(nets))),
                            'ic': float(total_ic_loss / max(1, len(nets)))
                        },
                        geomtime_col=subdomain_collocs[0]
                    )
                except Exception as _diag_err:
                    print(f"[WARN] XPINN diagnostics logging failed at {i}: {_diag_err}")

            if i % 100 == 0:
                avg_loss = sum(subdomain_losses) / len(subdomain_losses)
                # Average component losses across subdomains
                avg_pde = total_pde_loss / len(nets)
                avg_ic = total_ic_loss / len(nets)
                avg_if_sol = total_interface_sol_loss / len(nets)
                avg_if_res = total_interface_res_loss / len(nets)
                
                print(f"XPINN Training Loss at {i} (Adam, per-subdomain) = {avg_loss:.2e}", flush=True)
                print(f"  Component losses: PDE={avg_pde:.2e} | IC={avg_ic:.2e} | IF_sol={avg_if_sol:.2e} | IF_res={avg_if_res:.2e}", flush=True)
        else:
            # Unified Adam training (single-GPU, original approach)
            if XPINN_ALTERNATING_TRAINING:
                # Alternate between subdomains (not yet implemented - would need separate optimizers)
                raise NotImplementedError("Alternating training not yet implemented")
            else:
                # Train all networks simultaneously
                loss, loss_dict = optimizer.step(make_closure(optimizer))
            
            # Diagnostics for XPINN unified every 50 iterations
            if i % 50 == 0 and len(nets) > 0 and len(subdomain_collocs) > 0 and xpinn_diagnostics is not None:
                try:
                    xpinn_diagnostics.log_iteration(
                        iteration=i,
                        model=nets[0],
                        loss_dict={
                            'total': loss.item(),
                            'pde': float(loss_dict.get('PDE', 0.0)),
                            'ic': float(loss_dict.get('IC', 0.0))
                        },
                        geomtime_col=subdomain_collocs[0]
                    )
                except Exception as _diag_err:
                    print(f"[WARN] XPINN diagnostics logging failed at {i}: {_diag_err}")

            if i % 100 == 0:
                with torch.autograd.no_grad():
                    print(f"XPINN Training Loss at {i} (Adam) = {loss.item():.2e}", flush=True)
                    # Print loss breakdown
                    breakdown_str = " | ".join([f"{k}: {v:.2e}" for k, v in loss_dict.items() if v > 0])
                    if breakdown_str:
                        print(f"  Loss breakdown: {breakdown_str}", flush=True)
    
    # L-BFGS training - per-subdomain optimization
    # Each subdomain network is optimized separately while others are frozen
    # This avoids multi-GPU gradient gathering issues and memory constraints
    if iterationL > 0:
        print("\nStarting per-subdomain L-BFGS training...")
        
        # Optimize each subdomain network separately
        for subdomain_idx in range(len(nets)):
            print(f"  Optimizing subdomain {subdomain_idx}...")
            
            net = nets[subdomain_idx]
            net_device = subdomain_devices[subdomain_idx] if subdomain_devices else device
            
            # Create optimizer for this subdomain only
            optimizer_sub = torch.optim.LBFGS(
                net.parameters(), line_search_fn='strong_wolfe')
            
            # Create closure for this subdomain
            # Computes loss for this subdomain + its interface losses
            def make_subdomain_lbfgs_closure(sub_idx, current_net):
                def subdomain_closure():
                    optimizer_sub.zero_grad()
                    
                    # Compute PDE and IC loss for this subdomain
                    colloc = subdomain_collocs[sub_idx]
                    colloc_ic = subdomain_ic_collocs[sub_idx]
                    cached_ic = cached_ic_values[sub_idx] if cached_ic_values else None
                    
                    pde_loss = xpinn_loss_model.compute_pde_loss(colloc, current_net)
                    ic_loss = xpinn_loss_model.compute_ic_loss(colloc_ic, current_net, ic_functions, cached_ic)
                    
                    total_loss = pde_loss + ic_loss
                    
                    # Add interface losses where this subdomain is involved
                    for interface in interfaces:
                        subdomain_i, subdomain_j, _, _ = interface
                        interface_key = (subdomain_i, subdomain_j)
                        
                        # Only compute interface losses where this subdomain participates
                        if sub_idx == subdomain_i or sub_idx == subdomain_j:
                            if interface_key in interface_collocs:
                                colloc_interface = interface_collocs[interface_key]
                                net1 = nets[subdomain_i]
                                net2 = nets[subdomain_j]
                                
                                # Compute interface losses (gradients only flow to this net)
                                sol_loss = xpinn_loss_model.compute_interface_solution_loss(
                                    colloc_interface, net1, net2)
                                res_loss = xpinn_loss_model.compute_interface_residual_loss(
                                    colloc_interface, net1, net2)
                                
                                # Move interface losses to current net's device before adding
                                current_device = next(current_net.parameters()).device
                                sol_loss = sol_loss.to(current_device)
                                res_loss = res_loss.to(current_device)
                                
                                total_loss = total_loss + sol_loss + res_loss
                    
                    # L-BFGS will call this closure multiple times for line search
                    # Use retain_graph=True to allow multiple backward passes
                    total_loss.backward(retain_graph=True)
                    return total_loss
                
                return subdomain_closure
            
            # Helper to compute and print a detailed loss breakdown for this subdomain (no grad)
            def _lbfgs_subdomain_breakdown(sub_idx, current_net):
                with torch.no_grad():
                    colloc = subdomain_collocs[sub_idx]
                    colloc_ic = subdomain_ic_collocs[sub_idx]
                    cached_ic = cached_ic_values[sub_idx] if cached_ic_values else None
                    pde_loss = xpinn_loss_model.compute_pde_loss(colloc, current_net)
                    ic_loss = xpinn_loss_model.compute_ic_loss(colloc_ic, current_net, ic_functions, cached_ic)
                    if len(nets) > 1:
                        device0 = next(current_net.parameters()).device
                        pde_loss = pde_loss.to(device0)
                        ic_loss = ic_loss.to(device0)
                    if_sol = torch.tensor(0.0, device=next(current_net.parameters()).device)
                    if_res = torch.tensor(0.0, device=next(current_net.parameters()).device)
                    for interface in interfaces:
                        subdomain_i, subdomain_j, _, _ = interface
                        interface_key = (subdomain_i, subdomain_j)
                        if sub_idx == subdomain_i or sub_idx == subdomain_j:
                            if interface_key in interface_collocs:
                                colloc_interface = interface_collocs[interface_key]
                                net1 = nets[subdomain_i]
                                net2 = nets[subdomain_j]
                                sol_loss = xpinn_loss_model.compute_interface_solution_loss(colloc_interface, net1, net2)
                                res_loss = xpinn_loss_model.compute_interface_residual_loss(colloc_interface, net1, net2)
                                current_device = next(current_net.parameters()).device
                                if_sol = if_sol + sol_loss.to(current_device)
                                if_res = if_res + res_loss.to(current_device)
                    total = pde_loss + ic_loss + if_sol + if_res
                    return total.item(), pde_loss.item(), ic_loss.item(), if_sol.item(), if_res.item()

            # Run L-BFGS for this subdomain
            for i in range(iterationL):
                loss = optimizer_sub.step(make_subdomain_lbfgs_closure(subdomain_idx, net))
                
                if i % 50 == 0:
                    total_v, pde_v, ic_v, if_sol_v, if_res_v = _lbfgs_subdomain_breakdown(subdomain_idx, net)
                    print(
                        f"    Subdomain {subdomain_idx} L-BFGS step {i}: "
                        f"Total={total_v:.2e} | PDE={pde_v:.2e} | IC={ic_v:.2e} | "
                        f"IF_sol={if_sol_v:.2e} | IF_res={if_res_v:.2e}",
                        flush=True
                    )
        
        print("Per-subdomain L-BFGS training completed.")
    
    # Generate diagnostic plots at the end of XPINN training
    if xpinn_diagnostics is not None:
        try:
            final_iteration = iteration_adam + iterationL - 1
            xpinn_diagnostics.plot_diagnostics(final_iteration)
        except Exception as _diag_err:
            print(f"[WARN] Final XPINN diagnostics plotting failed: {_diag_err}")
    
    print("XPINN training completed.")
_register_module('training.trainer', ['train', 'train_xpinn'])

